INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p259-2', 'doc-14-nist-sp-800-53', '', 259, 'Control Enhancements: (1) PERSONALLY IDENTIFIABLE INFORMATION PROCESSING PURPOSES | DATA TAGGING Attach data tags containing the following purposes to [Assignment: organization-defined elements of personally identifiable information]: [Assignment: organization-defined processing purposes].', 'kb-doc-14-nist-sp-800-53-p259-2', 0, 30, '14-nist-sp-800-53', 'retrieved', '849C54BE406E3B3E937506886DD98768A1E79DBF61CFD1B2E3499F5A12101FDE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p259-3', 'doc-14-nist-sp-800-53', '', 259, 'Discussion: Data tags support the tracking of processing purposes by conveying the purposes along with the relevant elements of personally identifiable information throughout the system. By conveying the processing purposes in a data tag along with the personally identifiable information as the information transits a system, a system owner or operator can identify whether a change in processing would be compatible with the identified and documented purposes. Data tags may also support the use of automated tools.', 'kb-doc-14-nist-sp-800-53-p259-3', 0, 77, '14-nist-sp-800-53', 'retrieved', 'EC572FBF80E03D42825F319DFA695FAF4B057BB28AE2DAF1D70A280B9FB7EB1F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p259-5', 'doc-14-nist-sp-800-53', '', 259, '(2) PERSONALLY IDENTIFIABLE INFORMATION PROCESSING PURPOSES | AUTOMATION Track processing purposes of personally identifiable information using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p259-5', 0, 20, '14-nist-sp-800-53', 'retrieved', '8BAFCB8AB76583475216090A6FA6DD0FE611E8BAB649645E616540F23E613A43', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
