VALUES ('doc-14-nist-sp-800-53-p263-1', 'doc-14-nist-sp-800-53', '', 263, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 236 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p263-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '245639B836BDEFBAE526FFB5D14606459B25569BEE2C2333F58D7BE03ABFCB38', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
