VALUES ('doc-14-nist-sp-800-53-p265-1', 'doc-14-nist-sp-800-53', '', 265, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 238 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p265-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '23CC70673D228B2DFB7A6099ECBAF984BD9C26929D6F386253AED2B32D155361', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
