VALUES ('doc-14-nist-sp-800-53-p266-1', 'doc-14-nist-sp-800-53', '', 266, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 239 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p266-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'BE838703F39DD8982A442E0EC3E7416CC64A295D5F41077A025C872F5657D167', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
