INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p267-2', 'doc-14-nist-sp-800-53', '', 267, 'Alternatively, organizations can apply the guidance in [CNSSI 1253] for security objective- related categorization.', 'kb-doc-14-nist-sp-800-53-p267-2', 0, 14, '14-nist-sp-800-53', 'retrieved', 'FB76825AE449023FE52203D6F7BEFCF6A1C6FC8BC7C25167E1FFADD446855304', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
