INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p267-4', 'doc-14-nist-sp-800-53', '', 267, 'References: [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-60-1], [SP 800- 60-2], [SP 800-160-1], [CNSSI 1253], [NARA CUI].', 'kb-doc-14-nist-sp-800-53-p267-4', 0, 22, '14-nist-sp-800-53', 'retrieved', '18EDE9F07CCC8C78A1DA1F50C60BB310E841E08CB20B1713DD237CB30CFD4EF7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
