INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p267-10', 'doc-14-nist-sp-800-53', '', 267, 'Risk assessments can play an important role in control selection processes, particularly during the application of tailoring guidance and in the earliest phases of capability determination.', 'kb-doc-14-nist-sp-800-53-p267-10', 0, 26, '14-nist-sp-800-53', 'retrieved', 'BB8EB8A0174727D085970596CB74B04797C3E2B2EFF1D94F77CC514860AFD59A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
