VALUES ('doc-14-nist-sp-800-53-p268-1', 'doc-14-nist-sp-800-53', '', 268, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 241 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p268-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'A31AE82E934D488ACE6539CB0C9252E325F2DF729DF681B620E3D94793770967', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
