VALUES ('doc-14-nist-sp-800-53-p269-1', 'doc-14-nist-sp-800-53', '', 269, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 242 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p269-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C175245A7E6C6B8B665CC46FB45513C4C5DB5B182D93FACFF4D9713BB1DD83EF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
