VALUES ('doc-14-nist-sp-800-53-p269-4', 'doc-14-nist-sp-800-53', '', 269, 'References: [OMB A-130], [SP 800-30], [SP 800-39], [SP 800-161], [IR 8023], [IR 8062], [IR 8272].', 'kb-doc-14-nist-sp-800-53-p269-4', 0, 15, '14-nist-sp-800-53', 'retrieved', 'DC6D98CFD84F472C0B6B550CC32B174F58D19B0D276DA168E9A38A2736BE1F5B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
