INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p270-7', 'doc-14-nist-sp-800-53', '', 270, 'Control Enhancements: (1) VULNERABILITY MONITORING AND SCANNING | UPDATE TOOL CAPABILITY [Withdrawn: Incorporated into RA-5.] (2) VULNERABILITY MONITORING AND SCANNING | UPDATE VULNERABILITIES TO BE SCANNED Update the system vulnerabilities to be scanned [Selection (one or more): [Assignment: organization-defined frequency]; prior to a new scan; when new vulnerabilities are identified and reported].', 'kb-doc-14-nist-sp-800-53-p270-7', 0, 52, '14-nist-sp-800-53', 'retrieved', 'E153E04DD0B1370CF47A8912E771FC9362D6E995A52856C26E879BB394498A86', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p270-8', 'doc-14-nist-sp-800-53', '', 270, 'Discussion: Due to the complexity of modern software, systems, and other factors, new vulnerabilities are discovered on a regular basis. It is important that newly discovered vulnerabilities are added to the list of vulnerabilities to be scanned to ensure that the organization can take steps to mitigate those vulnerabilities in a timely manner.', 'kb-doc-14-nist-sp-800-53-p270-8', 0, 53, '14-nist-sp-800-53', 'retrieved', 'CB83B4182FDF0E5BDCD7A16ACEF8A36B7A5D389001151409307B9C2954F54D98', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p270-10', 'doc-14-nist-sp-800-53', '', 270, '(3) VULNERABILITY MONITORING AND SCANNING | BREADTH AND DEPTH OF COVERAGE Define the breadth and depth of vulnerability scanning coverage.', 'kb-doc-14-nist-sp-800-53-p270-10', 0, 20, '14-nist-sp-800-53', 'retrieved', '1CBE908774E7A0131636945849D06A7B3263040CBAB3062860AAC6091683F70E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p270-11', 'doc-14-nist-sp-800-53', '', 270, 'Discussion: The breadth of vulnerability scanning coverage can be expressed as a percentage of components within the system, by the particular types of systems, by the criticality of systems, or by the number of vulnerabilities to be checked. Conversely, the depth of vulnerability scanning coverage can be expressed as the level of the system design that the organization intends to monitor (e.g., component, module, subsystem, element).', 'kb-doc-14-nist-sp-800-53-p270-11', 0, 66, '14-nist-sp-800-53', 'retrieved', '045AAF549DBDFE79A115D79C2D80815FCEEF270ABF7C093AF574690E3541EC16', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-1', 'doc-14-nist-sp-800-53', '', 271, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 244 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p271-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D912464276067BCAC81CEE38F0F2C688B7F5F144681D8A34F427E32C9F8A7859', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-2', 'doc-14-nist-sp-800-53', '', 271, 'Organizations can determine the sufficiency of vulnerability scanning coverage with regard to its risk tolerance and other factors. Scanning tools and how the tools are configured may affect the depth and coverage. Multiple scanning tools may be needed to achieve the desired depth and coverage. [SP 800-53A] provides additional information on the breadth and depth of coverage.', 'kb-doc-14-nist-sp-800-53-p271-2', 0, 57, '14-nist-sp-800-53', 'retrieved', '2294B970C45DAE5132085657C5D70752DEBBA7C555ADDF842B97E89E43ED7071', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-4', 'doc-14-nist-sp-800-53', '', 271, '(4) VULNERABILITY MONITORING AND SCANNING | DISCOVERABLE INFORMATION Determine information about the system that is discoverable and take [Assignment: organization-defined corrective actions].', 'kb-doc-14-nist-sp-800-53-p271-4', 0, 22, '14-nist-sp-800-53', 'retrieved', '98EA78BE081B0A9274F7F1AA42CE7F6045DD014CACC40DB78106BCD60572D141', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-5', 'doc-14-nist-sp-800-53', '', 271, 'Discussion: Discoverable information includes information that adversaries could obtain without compromising or breaching the system, such as by collecting information that the system is exposing or by conducting extensive web searches. Corrective actions include notifying appropriate organizational personnel, removing designated information, or changing the system to make the designated information less relevant or attractive to adversaries. This enhancement excludes intentionally discoverable information that may be part of a decoy capability (e.g., honeypots, honeynets, or deception nets) deployed by the organization.', 'kb-doc-14-nist-sp-800-53-p271-5', 0, 80, '14-nist-sp-800-53', 'retrieved', '7CA1FEB8BF2287DF2A03FDF8998F9F9FF7C40B2D84E496D69B3C08AFA09C0991', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-7', 'doc-14-nist-sp-800-53', '', 271, '(5) VULNERABILITY MONITORING AND SCANNING | PRIVILEGED ACCESS Implement privileged access authorization to [Assignment: organization-defined system components] for [Assignment: organization-defined vulnerability scanning activities].', 'kb-doc-14-nist-sp-800-53-p271-7', 0, 23, '14-nist-sp-800-53', 'retrieved', 'CB65FD984FA695495C91698B738C2878552A52549D8F9E644DD5799E2595729D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-8', 'doc-14-nist-sp-800-53', '', 271, 'Discussion: In certain situations, the nature of the vulnerability scanning may be more intrusive, or the system component that is the subject of the scanning may contain classified or controlled unclassified information, such as personally identifiable information. Privileged access authorization to selected system components facilitates more thorough vulnerability scanning and protects the sensitive nature of such scanning.', 'kb-doc-14-nist-sp-800-53-p271-8', 0, 57, '14-nist-sp-800-53', 'retrieved', '1A7D34FEAB567593CB870EFA9A6CA5DC9C3D1DBEC7108A0D5195FE9E91B85265', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-10', 'doc-14-nist-sp-800-53', '', 271, '(6) VULNERABILITY MONITORING AND SCANNING | AUTOMATED TREND ANALYSES Compare the results of multiple vulnerability scans using [Assignment: organization- defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p271-10', 0, 22, '14-nist-sp-800-53', 'retrieved', 'A05E95CE2D428B3A6040D8F075BAA9C3720431A1D4FDF9BC3323405ED17CE276', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-11', 'doc-14-nist-sp-800-53', '', 271, 'Discussion: Using automated mechanisms to analyze multiple vulnerability scans over time can help determine trends in system vulnerabilities and identify patterns of attack.', 'kb-doc-14-nist-sp-800-53-p271-11', 0, 23, '14-nist-sp-800-53', 'retrieved', 'C9E844EE63060AFEEADF6ABBD3991EE0D6B0134F7E8730EBA31971E86945EAC3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-13', 'doc-14-nist-sp-800-53', '', 271, '(7) VULNERABILITY MONITORING AND SCANNING | AUTOMATED DETECTION AND NOTIFICATION OF UNAUTHORIZED COMPONENTS [Withdrawn: Incorporated into CM-8.] (8) VULNERABILITY MONITORING AND SCANNING | REVIEW HISTORIC AUDIT LOGS Review historic audit logs to determine if a vulnerability identified in a [Assignment: organization-defined system] has been previously exploited within an [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p271-13', 0, 52, '14-nist-sp-800-53', 'retrieved', 'C21356DC4DEC17CD334AE6AD0A2C2FDFCA37F68888FEAE1EDCF8EC2F88962E2D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p271-14', 'doc-14-nist-sp-800-53', '', 271, 'Discussion: Reviewing historic audit logs to determine if a recently detected vulnerability in a system has been previously exploited by an adversary can provide important information for forensic analyses. Such analyses can help identify, for example, the extent of a previous intrusion, the trade craft employed during the attack, organizational information exfiltrated or modified, mission or business capabilities affected, and the duration of the attack.', 'kb-doc-14-nist-sp-800-53-p271-14', 0, 65, '14-nist-sp-800-53', 'retrieved', 'B507E2690EDB57872CC4F0E0187FE65354D349A13271AE4A9EA8995D141E9AE5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-1', 'doc-14-nist-sp-800-53', '', 272, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 245 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p272-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '301D0DFA0E66C5E8CDC9F1B301AFF2DF16004806D433F94B28E173257E9BD81A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-2', 'doc-14-nist-sp-800-53', '', 272, '(9) VULNERABILITY MONITORING AND SCANNING | PENETRATION TESTING AND ANALYSES [Withdrawn: Incorporated into CA-8.] (10) VULNERABILITY MONITORING AND SCANNING | CORRELATE SCANNING INFORMATION Correlate the output from vulnerability scanning tools to determine the presence of multi- vulnerability and multi-hop attack vectors.', 'kb-doc-14-nist-sp-800-53-p272-2', 0, 41, '14-nist-sp-800-53', 'retrieved', '129A466BF0678802378EBFC854C982834F1405BC45FCD1191BF088B124E08EB8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-3', 'doc-14-nist-sp-800-53', '', 272, 'Discussion: An attack vector is a path or means by which an adversary can gain access to a system in order to deliver malicious code or exfiltrate information. Organizations can use attack trees to show how hostile activities by adversaries interact and combine to produce adverse impacts or negative consequences to systems and organizations. Such information, together with correlated data from vulnerability scanning tools, can provide greater clarity regarding multi-vulnerability and multi-hop attack vectors. The correlation of vulnerability scanning information is especially important when organizations are transitioning from older technologies to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols).', 'kb-doc-14-nist-sp-800-53-p272-3', 0, 101, '14-nist-sp-800-53', 'retrieved', 'CFDDB9E08CA591960CD0C5483763A400EB26188FB70AE9EB993F02DA420F0270', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-4', 'doc-14-nist-sp-800-53', '', 272, 'During such transitions, some system components may inadvertently be unmanaged and create opportunities for adversary exploitation.', 'kb-doc-14-nist-sp-800-53-p272-4', 0, 16, '14-nist-sp-800-53', 'retrieved', 'E714A37661E3C55F1E7213018B311B5E0D8149FE904B682E4E02B53637696BE3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-6', 'doc-14-nist-sp-800-53', '', 272, '(11) VULNERABILITY MONITORING AND SCANNING | PUBLIC DISCLOSURE PROGRAM Establish a public reporting channel for receiving reports of vulnerabilities in organizational systems and system components.', 'kb-doc-14-nist-sp-800-53-p272-6', 0, 25, '14-nist-sp-800-53', 'retrieved', 'C392E209B87928C9EAFD11C7EBF7EECFF1222B75C894D3976EC32A791B9AC8AE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
