INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-7', 'doc-14-nist-sp-800-53', '', 272, 'Discussion: The reporting channel is publicly discoverable and contains clear language authorizing good-faith research and the disclosure of vulnerabilities to the organization. The organization does not condition its authorization on an expectation of indefinite non- disclosure to the public by the reporting entity but may request a specific time period to properly remediate the vulnerability.', 'kb-doc-14-nist-sp-800-53-p272-7', 0, 55, '14-nist-sp-800-53', 'retrieved', 'B1622C03B4D8991D94263A4B4369BEAC316B6DB47E128021168D81A7CD088ACE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
