INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p272-10', 'doc-14-nist-sp-800-53', '', 272, 'RA-6 TECHNICAL SURVEILLANCE COUNTERMEASURES SURVEY Control: Employ a technical surveillance countermeasures survey at [Assignment: organization- defined locations] [Selection (one or more): [Assignment: organization-defined frequency]; when the following events or indicators occur: [Assignment: organization-defined events or indicators]].', 'kb-doc-14-nist-sp-800-53-p272-10', 0, 36, '14-nist-sp-800-53', 'retrieved', '2A19AC429C70AFB08BD502EEDDB2B0EA7CCEF7DC5E5382A84E57A3D5ED782BEE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
