INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p273-2', 'doc-14-nist-sp-800-53', '', 273, 'RA-7 RISK RESPONSE Control: Respond to findings from security and privacy assessments, monitoring, and audits in accordance with organizational risk tolerance.', 'kb-doc-14-nist-sp-800-53-p273-2', 0, 21, '14-nist-sp-800-53', 'retrieved', '6F89E4ACBF69E1E1955BDA653E134BA694CCAFB909537C5EEBB7F22FE05FE755', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p273-3', 'doc-14-nist-sp-800-53', '', 273, 'Discussion: Organizations have many options for responding to risk including mitigating risk by implementing new controls or strengthening existing controls, accepting risk with appropriate justification or rationale, sharing or transferring risk, or avoiding risk. The risk tolerance of the organization influences risk response decisions and actions. Risk response addresses the need to determine an appropriate response to risk before generating a plan of action and milestones entry. For example, the response may be to accept risk or reject risk, or it may be possible to mitigate the risk immediately so that a plan of action and milestones entry is not needed.', 'kb-doc-14-nist-sp-800-53-p273-3', 0, 101, '14-nist-sp-800-53', 'retrieved', 'CEC41D1E4DD6E7A21B87CFBE6F759DD4C0740F37263A7EE5CF2CE5588AC67621', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p273-4', 'doc-14-nist-sp-800-53', '', 273, 'However, if the risk response is to mitigate the risk, and the mitigation cannot be completed immediately, a plan of action and milestones entry is generated.', 'kb-doc-14-nist-sp-800-53-p273-4', 0, 26, '14-nist-sp-800-53', 'retrieved', 'DD827880FFDAADCFDB3B3027343002D8CD7F1EBB589CF346602744409C96D53E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
