VALUES ('doc-14-nist-sp-800-53-p273-7', 'doc-14-nist-sp-800-53', '', 273, 'References: [FIPS 199], [FIPS 200], [SP 800-30], [SP 800-37], [SP 800-39], [SP 800-160-1].', 'kb-doc-14-nist-sp-800-53-p273-7', 0, 13, '14-nist-sp-800-53', 'retrieved', '2D838BFCD0462F9BB5C4EF6C513BFF7411F58DEC5EA03F73F351FD785A69F10D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
