INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p275-2', 'doc-14-nist-sp-800-53', '', 275, 'a. Establish and maintain a cyber threat hunting capability to: 1. Search for indicators of compromise in organizational systems; and 2. Detect, track, and disrupt threats that evade existing controls; and b. Employ the threat hunting capability [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p275-2', 0, 40, '14-nist-sp-800-53', 'retrieved', '1D720CAD87E3A6C02C485F75E8AF662FEFAD583760CB50BCFA2C895CBB9FDE88', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
