VALUES ('doc-14-nist-sp-800-53-p276-1', 'doc-14-nist-sp-800-53', '', 276, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 249 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p276-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'EF99AFB0044EEA0B21C7631049C047B11EFC9233B49BA289F38519BC77D8D9CB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
