VALUES ('doc-14-nist-sp-800-53-p277-1', 'doc-14-nist-sp-800-53', '', 277, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 250 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p277-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0CE2ED7AF939DCDF9A84E1F62A1A9B032F27D153CB0AF00DACA22223DCE9227A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
