INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p277-2', 'doc-14-nist-sp-800-53', '', 277, 'SA-2 ALLOCATION OF RESOURCES Control: a. Determine the high-level information security and privacy requirements for the system or system service in mission and business process planning; b. Determine, document, and allocate the resources required to protect the system or system service as part of the organizational capital planning and investment control process; and c. Establish a discrete line item for information security and privacy in organizational programming and budgeting documentation.', 'kb-doc-14-nist-sp-800-53-p277-2', 0, 70, '14-nist-sp-800-53', 'retrieved', '49565B04EB5117FF57E22CC0EAAB3600BF2E912F765FB0D4595C929A5FC20652', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
