INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p277-3', 'doc-14-nist-sp-800-53', '', 277, 'Discussion: Resource allocation for information security and privacy includes funding for system and services acquisition, sustainment, and supply chain-related risks throughout the system development life cycle.', 'kb-doc-14-nist-sp-800-53-p277-3', 0, 26, '14-nist-sp-800-53', 'retrieved', 'B60593A6E71CFB9E60168E86C5335048B286E43C9B76C1FB16335B8D0D1C5C67', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
