VALUES ('doc-14-nist-sp-800-53-p278-2', 'doc-14-nist-sp-800-53', '', 278, 'and supply chain risk management functions and controls play significant roles in the effective management of the system during the life cycle.', 'kb-doc-14-nist-sp-800-53-p278-2', 0, 22, '14-nist-sp-800-53', 'retrieved', '03FE2FF377D596B84FA2184724C70B62536678CB7CB77B33EE50591CA16D7F18', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
