VALUES ('doc-14-nist-sp-800-53-p278-3', 'doc-14-nist-sp-800-53', '', 278, 'Related Controls: AT-3, PL-8, PM-7, SA-4, SA-5, SA-8, SA-11, SA-15, SA-17, SA-22, SR-3, SR-4, SR- 5, SR-9.', 'kb-doc-14-nist-sp-800-53-p278-3', 0, 17, '14-nist-sp-800-53', 'retrieved', '74136F3F3E2DB8F772FE235DB1151693900E7245AC7FA9250463BADB935A3ACA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
