INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p278-4', 'doc-14-nist-sp-800-53', '', 278, 'Control Enhancements: (1) SYSTEM DEVELOPMENT LIFE CYCLE | MANAGE PREPRODUCTION ENVIRONMENT Protect system preproduction environments commensurate with risk throughout the system development life cycle for the system, system component, or system service.', 'kb-doc-14-nist-sp-800-53-p278-4', 0, 32, '14-nist-sp-800-53', 'retrieved', 'DA630F326EB27A3A8F6781459F1919C32AAC0A302A4B45C95D8EF59230024098', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p278-5', 'doc-14-nist-sp-800-53', '', 278, 'Discussion: The preproduction environment includes development, test, and integration environments. The program protection planning processes established by the Department of Defense are examples of managing the preproduction environment for defense contractors.', 'kb-doc-14-nist-sp-800-53-p278-5', 0, 31, '14-nist-sp-800-53', 'retrieved', 'C86C309647F8C4FF3C83A6F833AF8B320F587913682993BC9DBBB35BB3F0137A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
