VALUES ('doc-14-nist-sp-800-53-p279-1', 'doc-14-nist-sp-800-53', '', 279, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 252 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p279-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '366F177A9B11B02F0FF4093B9C491327ED3C0F7CF37C00650EE72EB6E0171E28', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
