VALUES ('doc-14-nist-sp-800-53-p280-1', 'doc-14-nist-sp-800-53', '', 280, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 253 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p280-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '85DEAF610D075DE1E1EA5BADB083269B81F9D018CDD83F389E0930E72742EC0C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
