VALUES ('doc-14-nist-sp-800-53-p281-1', 'doc-14-nist-sp-800-53', '', 281, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 254 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p281-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '84AF1B6AA7583E3724F28398A70902DB19F08931B3C4AF2FDB71A4A4E11F2ACC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
