INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-2', 'doc-14-nist-sp-800-53', '', 281, '[Withdrawn: Incorporated into CM-8(9).] (5) ACQUISITION PROCESS | SYSTEM, COMPONENT, AND SERVICE CONFIGURATIONS Require the developer of the system, system component, or system service to: (a) Deliver the system, component, or service with [Assignment: organization-defined security configurations] implemented; and (b) Use the configurations as the default for any subsequent system, component, or service reinstallation or upgrade.', 'kb-doc-14-nist-sp-800-53-p281-2', 0, 56, '14-nist-sp-800-53', 'retrieved', '509AD98A278F9900784542669F1E97C18DF7CF65406B6EA108663F4079F0B373', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-3', 'doc-14-nist-sp-800-53', '', 281, 'Discussion: Examples of security configurations include the U.S. Government Configuration Baseline (USGCB), Security Technical Implementation Guides (STIGs), and any limitations on functions, ports, protocols, and services. Security characteristics can include requiring that default passwords have been changed.', 'kb-doc-14-nist-sp-800-53-p281-3', 0, 37, '14-nist-sp-800-53', 'retrieved', '95950411EFDF6B42DF10B978B52B522E42A6676BDB96146EB4233BDE2F280B76', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-5', 'doc-14-nist-sp-800-53', '', 281, '(6) ACQUISITION PROCESS | USE OF INFORMATION ASSURANCE PRODUCTS (a) Employ only government off-the-shelf or commercial off-the-shelf information assurance and information assurance-enabled information technology products that compose an NSA-approved solution to protect classified information when the networks used to transmit the information are at a lower classification level than the information being transmitted; and (b) Ensure that these products have been evaluated and/or validated by NSA or in accordance with NSA-approved procedures.', 'kb-doc-14-nist-sp-800-53-p281-5', 0, 72, '14-nist-sp-800-53', 'retrieved', '685030C281CF021994711DF1AA9560E0A508AE25C08B6C6BD8687B087AB9B3C0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-6', 'doc-14-nist-sp-800-53', '', 281, 'Discussion: Commercial off-the-shelf IA or IA-enabled information technology products used to protect classified information by cryptographic means may be required to use NSA- approved key management. See [NSA CSFC].', 'kb-doc-14-nist-sp-800-53-p281-6', 0, 29, '14-nist-sp-800-53', 'retrieved', '8E23E035B7BECD79015412B10BB6756D5B5DA70406197C9BEC89E3AF874CA7AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
