INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-8', 'doc-14-nist-sp-800-53', '', 281, '(7) ACQUISITION PROCESS | NIAP-APPROVED PROTECTION PROFILES (a) Limit the use of commercially provided information assurance and information assurance-enabled information technology products to those products that have been successfully evaluated against a National Information Assurance partnership (NIAP)- approved Protection Profile for a specific technology type, if such a profile exists; and (b) Require, if no NIAP-approved Protection Profile exists for a specific technology type but a commercially provided information technology product relies on cryptographic functionality to enforce its security policy, that the cryptographic module is FIPS- validated or NSA-approved.', 'kb-doc-14-nist-sp-800-53-p281-8', 0, 89, '14-nist-sp-800-53', 'retrieved', 'EC730EC510E4B2FC023FBD6C06C3BB23BF88AF98B9CB66CDB55C7D18E07254AA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-9', 'doc-14-nist-sp-800-53', '', 281, 'Discussion: See [NIAP CCEVS] for additional information on NIAP. See [NIST CMVP ] for additional information on FIPS-validated cryptographic modules.', 'kb-doc-14-nist-sp-800-53-p281-9', 0, 20, '14-nist-sp-800-53', 'retrieved', 'F006197E0A2D0B2B6F8A44C88FBDE5FECDCB9A97344C1F97C3C841F54E7BE165', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
