INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-11', 'doc-14-nist-sp-800-53', '', 281, '(8) ACQUISITION PROCESS | CONTINUOUS MONITORING PLAN FOR CONTROLS Require the developer of the system, system component, or system service to produce a plan for continuous monitoring of control effectiveness that is consistent with the continuous monitoring program of the organization.', 'kb-doc-14-nist-sp-800-53-p281-11', 0, 41, '14-nist-sp-800-53', 'retrieved', '843D0FA22259B7FBF4CFC4683783A5548BD11FF73F49D6DCCE07C5CC7586891B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-12', 'doc-14-nist-sp-800-53', '', 281, 'Discussion: The objective of continuous monitoring plans is to determine if the planned, required, and deployed controls within the system, system component, or system service continue to be effective over time based on the inevitable changes that occur. Developer continuous monitoring plans include a sufficient level of detail such that the information can be incorporated into continuous monitoring programs implemented by organizations.', 'kb-doc-14-nist-sp-800-53-p281-12', 0, 62, '14-nist-sp-800-53', 'retrieved', 'F843342BE8BBB6FC70275542D900F3B75C5EA2622B4A19B7237FFF6B1DD32D56', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p281-13', 'doc-14-nist-sp-800-53', '', 281, 'Continuous monitoring plans can include the types of control assessment and monitoring', 'kb-doc-14-nist-sp-800-53-p281-13', 0, 12, '14-nist-sp-800-53', 'retrieved', '2E75D4E84497C8159ED4B8F05723A46CCA8D14AB66833D714C70CD42504D4522', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
