VALUES ('doc-14-nist-sp-800-53-p282-2', 'doc-14-nist-sp-800-53', '', 282, 'activities planned, frequency of control monitoring, and actions to be taken when controls fail or become ineffective.', 'kb-doc-14-nist-sp-800-53-p282-2', 0, 17, '14-nist-sp-800-53', 'retrieved', '569A038E1D54BABADA0BD6543985C92AC4DE9898983E4E1464B246DADD4B5C94', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
