VALUES ('doc-14-nist-sp-800-53-p283-6', 'doc-14-nist-sp-800-53', '', 283, 'Control Enhancements: (1) SYSTEM DOCUMENTATION | FUNCTIONAL PROPERTIES OF SECURITY CONTROLS [Withdrawn: Incorporated into SA-4(1).] (2) SYSTEM DOCUMENTATION | SECURITY-RELEVANT EXTERNAL SYSTEM INTERFACES [Withdrawn: Incorporated into SA-4(2).] (3) SYSTEM DOCUMENTATION | HIGH-LEVEL DESIGN [Withdrawn: Incorporated into SA-4(2).]', 'kb-doc-14-nist-sp-800-53-p283-6', 0, 37, '14-nist-sp-800-53', 'retrieved', 'F668D884FFC9AFB802A580D16024CFE840F1E723BDAD8444A0EC0A381F5A216F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
