INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p284-3', 'doc-14-nist-sp-800-53', '', 284, 'SA-6 SOFTWARE USAGE RESTRICTIONS [Withdrawn: Incorporated into CM-10 and SI-7.] SA-7 USER-INSTALLED SOFTWARE [Withdrawn: Incorporated into CM-11 and SI-7.] SA-8 SECURITY AND PRIVACY ENGINEERING PRINCIPLES Control: Apply the following systems security and privacy engineering principles in the specification, design, development, implementation, and modification of the system and system components: [Assignment: organization-defined systems security and privacy engineering principles].', 'kb-doc-14-nist-sp-800-53-p284-3', 0, 57, '14-nist-sp-800-53', 'retrieved', '7DD6495B666FA68266A22CF79133619F22609923BD376659D035DAFD15CC6542', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
