VALUES ('doc-14-nist-sp-800-53-p284-7', 'doc-14-nist-sp-800-53', '', 284, 'Related Controls: PL-8, PM-7, RA-2, RA-3, RA-9, SA-3, SA-4, SA-15, SA-17, SA-20, SC-2, SC-3, SC- 32, SC-39, SR-2, SR-3, SR-4, SR-5.', 'kb-doc-14-nist-sp-800-53-p284-7', 0, 21, '14-nist-sp-800-53', 'retrieved', '236B394E9C1BAEC3C295E76998C76BD2E229C5E91E1B8268ABC2DF595529C401', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
