VALUES ('doc-14-nist-sp-800-53-p284-8', 'doc-14-nist-sp-800-53', '', 284, 'Control Enhancements: (1) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | CLEAR ABSTRACTIONS Implement the security design principle of clear abstractions.', 'kb-doc-14-nist-sp-800-53-p284-8', 0, 19, '14-nist-sp-800-53', 'retrieved', '112EA093C116FDFD4C8C529F0C0E33C9EE07CE985DF2E65C2248D7864F953B80', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
