INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p284-9', 'doc-14-nist-sp-800-53', '', 284, 'Discussion: The principle of clear abstractions states that a system has simple, well-defined interfaces and functions that provide a consistent and intuitive view of the data and how the data is managed. The clarity, simplicity, necessity, and sufficiency of the system interfaces—', 'kb-doc-14-nist-sp-800-53-p284-9', 0, 42, '14-nist-sp-800-53', 'retrieved', '74F48A2D09CD03F77FA8EBCDC4FAC4B354100A5A314BE9E22C600FF166664EDF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
