VALUES ('doc-14-nist-sp-800-53-p285-1', 'doc-14-nist-sp-800-53', '', 285, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 258 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p285-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '58DAC964364BA796A06F695A3D4E5EA18C1849E1F2584A99FFA2FAD29AB7A7C8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
