INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p285-2', 'doc-14-nist-sp-800-53', '', 285, 'combined with a precise definition of their functional behavior— promotes ease of analysis, inspection, and testing as well as the correct and secure use of the system. The clarity of an abstraction is subjective. Examples that reflect the application of this principle include avoidance of redundant, unused interfaces; information hiding; and avoidance of semantic overloading of interfaces or their parameters. Information hiding (i.e., representation- independent programming), is a design discipline used to ensure that the internal representation of information in one system component is not visible to another system component invoking or calling the first component, such that the published abstraction is not influenced by how the data may be managed internally.', 'kb-doc-14-nist-sp-800-53-p285-2', 0, 112, '14-nist-sp-800-53', 'retrieved', 'C28F1A05853A9316BCBC24A2E6F8A439C1DDD8D62D66220C9F838AC4CAE87DD1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
