INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p285-4', 'doc-14-nist-sp-800-53', '', 285, '(2) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | LEAST COMMON MECHANISM Implement the security design principle of least common mechanism in [Assignment: organization-defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p285-4', 0, 26, '14-nist-sp-800-53', 'retrieved', '3BBCFD970D3B8110E588685C723C827E5CF2D47A070F47803CA5499CF1F85420', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
