INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p285-13', 'doc-14-nist-sp-800-53', '', 285, 'Discussion: The principle of partially ordered dependencies states that the synchronization, calling, and other dependencies in the system are partially ordered. A fundamental concept in system design is layering, whereby the system is organized into well-defined, functionally', 'kb-doc-14-nist-sp-800-53-p285-13', 0, 37, '14-nist-sp-800-53', 'retrieved', '7F049F99B3AF425A0C18220CC49DFFACEDFA85AF11ABE5D8B798AB7194E9262C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
