INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p288-8', 'doc-14-nist-sp-800-53', '', 288, '(11) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | INVERSE MODIFICATION THRESHOLD Implement the security design principle of inverse modification threshold in [Assignment: organization-defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p288-8', 0, 26, '14-nist-sp-800-53', 'retrieved', 'A470EDB40E224ED0391D9AA85FEDE9EB18A8630EFEA0E884048DEBB8C75A469A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
