INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p289-2', 'doc-14-nist-sp-800-53', '', 289, '(12) SECURITY AND PRIVACY ENGINEERING PRINCIPLES | HIERARCHICAL PROTECTION Implement the security design principle of hierarchical protection in [Assignment: organization-defined systems or system components].', 'kb-doc-14-nist-sp-800-53-p289-2', 0, 24, '14-nist-sp-800-53', 'retrieved', 'C8D5D9712FB62B7CD3382E11B51DC3489BD47FAD0B4A0A00910F006608C3C226', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
