VALUES ('doc-14-nist-sp-800-53-p291-1', 'doc-14-nist-sp-800-53', '', 291, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 264 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p291-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0C93D553CB4AC6F48281FE4E0A1B8FCCFE8379E3405C7B7363A4643E8627303D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
