VALUES ('doc-14-nist-sp-800-53-p291-2', 'doc-14-nist-sp-800-53', '', 291, 'system-wide level of assurance of correct policy enforcement, the security architecture of a distributed composite system is thoroughly analyzed.', 'kb-doc-14-nist-sp-800-53-p291-2', 0, 19, '14-nist-sp-800-53', 'retrieved', '179BC3AB4FF350C30ECD07361A728A13FCFBA00A65A2317010B2E183ED0A0EA9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
