VALUES ('doc-14-nist-sp-800-53-p292-1', 'doc-14-nist-sp-800-53', '', 292, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 265 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p292-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '03AEFDAD369519F108A7379E0C3BD7BC93C99256FFD906D5B3746431C1B9AD31', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
