VALUES ('doc-14-nist-sp-800-53-p293-1', 'doc-14-nist-sp-800-53', '', 293, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 266 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p293-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D7D1460894F25DE93F79863B4FB225AF7F592B1DEB41D46C5CCF3A57B28EF055', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
