VALUES ('doc-14-nist-sp-800-53-p297-1', 'doc-14-nist-sp-800-53', '', 297, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 270 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p297-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '603E5F59A628DE23DFCC366267FD57D0D379DFA4790BB254D8E5C19A780114D0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
