INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p298-4', 'doc-14-nist-sp-800-53', '', 298, 'SA-9 EXTERNAL SYSTEM SERVICES Control: a. Require that providers of external system services comply with organizational security and privacy requirements and employ the following controls: [Assignment: organization-defined controls]; b. Define and document organizational oversight and user roles and responsibilities with regard to external system services; and c. Employ the following processes, methods, and techniques to monitor control compliance by external service providers on an ongoing basis: [Assignment: organization-defined processes, methods, and techniques].', 'kb-doc-14-nist-sp-800-53-p298-4', 0, 72, '14-nist-sp-800-53', 'retrieved', 'F731AEAB37BF0F5B094E872ADB271275279602665B518DABFA0C60358D5380F2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
