VALUES ('doc-14-nist-sp-800-53-p298-7', 'doc-14-nist-sp-800-53', '', 298, 'Related Controls: AC-20, CA-3, CP-2, IR-4, IR-7, PL-10, PL-11, PS-7, SA-2, SA-4, SR-3, SR-5.', 'kb-doc-14-nist-sp-800-53-p298-7', 0, 14, '14-nist-sp-800-53', 'retrieved', '3BB29206ED0B9C2693AD918C5D9282A4437A5D5741E102982C5CAC15104CA998', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
