INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p298-8', 'doc-14-nist-sp-800-53', '', 298, 'Control Enhancements: (1) EXTERNAL SYSTEM SERVICES | RISK ASSESSMENTS AND ORGANIZATIONAL APPROVALS (a) Conduct an organizational assessment of risk prior to the acquisition or outsourcing of information security services; and (b) Verify that the acquisition or outsourcing of dedicated information security services is approved by [Assignment: organization-defined personnel or roles].', 'kb-doc-14-nist-sp-800-53-p298-8', 0, 50, '14-nist-sp-800-53', 'retrieved', '1CA43FD6AC390DBA5A4671B3B00D3A08391C272B19ADE9D5AB6D6BF35D1C69F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
