INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p298-9', 'doc-14-nist-sp-800-53', '', 298, 'Discussion: Information security services include the operation of security devices, such as firewalls or key management services as well as incident monitoring, analysis, and response.', 'kb-doc-14-nist-sp-800-53-p298-9', 0, 25, '14-nist-sp-800-53', 'retrieved', '112160F6541FD32B4910EC04141DC2A72F72ECFBD288B36AC2460E4360D30411', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
