INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p298-10', 'doc-14-nist-sp-800-53', '', 298, 'Risks assessed can include system, mission or business, security, privacy, or supply chain risks.', 'kb-doc-14-nist-sp-800-53-p298-10', 0, 14, '14-nist-sp-800-53', 'retrieved', '86F261A66233D42A5F517EE1705342F29D1A2AE5DEA594A241F6BDEDE8656D8E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
