INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p298-12', 'doc-14-nist-sp-800-53', '', 298, '(2) EXTERNAL SYSTEM SERVICES | IDENTIFICATION OF FUNCTIONS, PORTS, PROTOCOLS, AND SERVICES Require providers of the following external system services to identify the functions, ports, protocols, and other services required for the use of such services: [Assignment: organization-defined external system services].', 'kb-doc-14-nist-sp-800-53-p298-12', 0, 41, '14-nist-sp-800-53', 'retrieved', '6B8EE351EFB9F845D3CB27A9F3E6AF019D1195C5061BC541D71E118E5E371BD5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
