INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p300-14', 'doc-14-nist-sp-800-53', '', 300, 'SA-10 DEVELOPER CONFIGURATION MANAGEMENT Control: Require the developer of the system, system component, or system service to: a. Perform configuration management during system, component, or service [Selection (one or more): design; development; implementation; operation; disposal]; b. Document, manage, and control the integrity of changes to [Assignment: organization- defined configuration items under configuration management]; c. Implement only organization-approved changes to the system, component, or service;', 'kb-doc-14-nist-sp-800-53-p300-14', 0, 64, '14-nist-sp-800-53', 'retrieved', 'CA910D16F3BCD6B8069382A3932B4955D850131DAEA34EA9962C8889480F3A58', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p301-1', 'doc-14-nist-sp-800-53', '', 301, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 274 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p301-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'E8827FC740033A402E731A6A2758E7A59B5BBE6C5A949A71646B16467980EC73', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
