INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p302-10', 'doc-14-nist-sp-800-53', '', 302, '(6) DEVELOPER CONFIGURATION MANAGEMENT | TRUSTED DISTRIBUTION Require the developer of the system, system component, or system service to execute procedures for ensuring that security-relevant hardware, software, and firmware updates distributed to the organization are exactly as specified by the master copies.', 'kb-doc-14-nist-sp-800-53-p302-10', 0, 42, '14-nist-sp-800-53', 'retrieved', '5C3159FC4C8AF5A959929F51CF6F14F7263B48A54AD9FA66472CB628644B3B54', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
