INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p302-11', 'doc-14-nist-sp-800-53', '', 302, 'Discussion: The trusted distribution of security-relevant hardware, software, and firmware updates help to ensure that the updates are correct representations of the master copies maintained by the developer and have not been tampered with during distribution.', 'kb-doc-14-nist-sp-800-53-p302-11', 0, 36, '14-nist-sp-800-53', 'retrieved', '8D53E70E9E50E9E2E80B8DF792B66B2A2C28F35B42B632C62E1C11892236B178', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
