INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p302-13', 'doc-14-nist-sp-800-53', '', 302, '(7) DEVELOPER CONFIGURATION MANAGEMENT | SECURITY AND PRIVACY REPRESENTATIVES Require [Assignment: organization-defined security and privacy representatives] to be included in the [Assignment: organization-defined configuration change management and control process].', 'kb-doc-14-nist-sp-800-53-p302-13', 0, 29, '14-nist-sp-800-53', 'retrieved', 'FBA5ED57E98DA66CFD7453BB4843E891E97A6980C3E8B3A1F7D6C9B4AF72F975', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
