INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p302-14', 'doc-14-nist-sp-800-53', '', 302, 'Discussion: Information security and privacy representatives can include system security officers, senior agency information security officers, senior agency officials for privacy, and system privacy officers. Representation by personnel with information security and privacy', 'kb-doc-14-nist-sp-800-53-p302-14', 0, 33, '14-nist-sp-800-53', 'retrieved', '4A06E6968FD21A21543071280111CC59B6CABD67ABA1B220732F001316C03987', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
