INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p303-2', 'doc-14-nist-sp-800-53', '', 303, 'expertise is important because changes to system configurations can have unintended side effects, some of which may be security- or privacy-relevant. Detecting such changes early in the process can help avoid unintended, negative consequences that could ultimately affect the security and privacy posture of systems. The configuration change management and control process in this control enhancement refers to the change management and control process defined by organizations in SA-10b.', 'kb-doc-14-nist-sp-800-53-p303-2', 0, 69, '14-nist-sp-800-53', 'retrieved', '83381D47ACBB52DB5D53EE43717C01C8B312C3E7BFE1FD87526C162D0B4B0796', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
