INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p303-4', 'doc-14-nist-sp-800-53', '', 303, 'References: [FIPS 140-3], [FIPS 180-4], [FIPS 202], [SP 800-128], [SP 800-160-1].', 'kb-doc-14-nist-sp-800-53-p303-4', 0, 11, '14-nist-sp-800-53', 'retrieved', '24DC6F51484DFC770E9D6F8711BFF8F57E0F60D2BD39C6F61449A6AD002F571D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
