VALUES ('doc-14-nist-sp-800-53-p304-1', 'doc-14-nist-sp-800-53', '', 304, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 277 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p304-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '78FDD6D8B4AA561A5995575A66D3A8D065712770AB178C34FC866F5445804947', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
