INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p305-2', 'doc-14-nist-sp-800-53', '', 305, '(b) Verify that the independent agent is provided with sufficient information to complete the verification process or granted the authority to obtain such information.', 'kb-doc-14-nist-sp-800-53-p305-2', 0, 24, '14-nist-sp-800-53', 'retrieved', '58781D41F05472DD4C406D63A804229DFA325EB35EAF50C621B8A11D6AA6D246', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
