INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p305-3', 'doc-14-nist-sp-800-53', '', 305, 'Discussion: Independent agents have the qualifications— including the expertise, skills, training, certifications, and experience— to verify the correct implementation of developer security and privacy assessment plans.', 'kb-doc-14-nist-sp-800-53-p305-3', 0, 26, '14-nist-sp-800-53', 'retrieved', 'FC0380DA749CD3FCD3D9F5BBF99B42CD60189E0926A7A9DCCF0204FF818AAD93', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
