VALUES ('doc-14-nist-sp-800-53-p308-4', 'doc-14-nist-sp-800-53', '', 308, 'Related Controls: MA-6, SA-3, SA-4, SA-8, SA-10, SA-11, SR-3, SR-4, SR-5, SR-6, SR-9.', 'kb-doc-14-nist-sp-800-53-p308-4', 0, 13, '14-nist-sp-800-53', 'retrieved', '28B6BFEFF610D5B68863AC6428043CDB7054F3E84134959053F037DD50FD84B4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
