INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p308-5', 'doc-14-nist-sp-800-53', '', 308, 'Control Enhancements: (1) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | QUALITY METRICS Require the developer of the system, system component, or system service to: (a) Define quality metrics at the beginning of the development process; and (b) Provide evidence of meeting the quality metrics [Selection (one or more): [Assignment: organization-defined frequency]; [Assignment: organization-defined program review milestones]; upon delivery].', 'kb-doc-14-nist-sp-800-53-p308-5', 0, 57, '14-nist-sp-800-53', 'retrieved', '96FED3C9FEA8B600E00355782079097016B3D8F8E9C9BD1C3F28843C2D2D7DD7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p308-6', 'doc-14-nist-sp-800-53', '', 308, 'Discussion: Organizations use quality metrics to establish acceptable levels of system quality. Metrics can include quality gates, which are collections of completion criteria or sufficiency standards that represent the satisfactory execution of specific phases of the system development project. For example, a quality gate may require the elimination of all compiler warnings or a determination that such warnings have no impact on the effectiveness of required security or privacy capabilities. During the execution phases of development projects, quality gates provide clear, unambiguous indications of progress.', 'kb-doc-14-nist-sp-800-53-p308-6', 0, 85, '14-nist-sp-800-53', 'retrieved', '96C1EC5D8A174B2480D5659BBBB0CCD8F1190105FCB3037D669788ABC22AEB52', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p308-7', 'doc-14-nist-sp-800-53', '', 308, 'Other metrics apply to the entire development project. Metrics can include defining the severity thresholds of vulnerabilities in accordance with organizational risk tolerance, such', 'kb-doc-14-nist-sp-800-53-p308-7', 0, 24, '14-nist-sp-800-53', 'retrieved', '9EB5048E704DD3393055B6B1C61DBD25B520F181F299E25A1ABEDDEAB78B8D3E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
