VALUES ('doc-14-nist-sp-800-53-p309-1', 'doc-14-nist-sp-800-53', '', 309, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 282 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p309-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '36087E25CE39C3DD605996AD091DCF3DBED653FC3AF32EFD7897F8F415EC6DB9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
