INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p309-4', 'doc-14-nist-sp-800-53', '', 309, '(2) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | SECURITY AND PRIVACY TRACKING TOOLS Require the developer of the system, system component, or system service to select and employ security and privacy tracking tools for use during the development process.', 'kb-doc-14-nist-sp-800-53-p309-4', 0, 38, '14-nist-sp-800-53', 'retrieved', '3DE8BD520FDB9909FA7AC5754FB8265412D0E9F1B55DC7E2AD546A0E09C75F8D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
