INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p309-5', 'doc-14-nist-sp-800-53', '', 309, 'Discussion: System development teams select and deploy security and privacy tracking tools, including vulnerability or work item tracking systems that facilitate assignment, sorting, filtering, and tracking of completed work items or tasks associated with development processes.', 'kb-doc-14-nist-sp-800-53-p309-5', 0, 36, '14-nist-sp-800-53', 'retrieved', '5A1A66BC8099A15A3F332D3654E859CF051BA257D4D0B052A4C92E9BB6AA39DB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
