INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p310-2', 'doc-14-nist-sp-800-53', '', 310, 'Require the developer of the system, system component, or system service to implement an explicit process to continuously improve the development process.', 'kb-doc-14-nist-sp-800-53-p310-2', 0, 22, '14-nist-sp-800-53', 'retrieved', '964CE484DC27B54A092EF92A2CFC894879EE34C56D0490BD68E45E87B598331D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
