INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p310-12', 'doc-14-nist-sp-800-53', '', 310, 'Discussion: The incident response plan provided by developers may provide information not readily available to organizations and be incorporated into organizational incident response plans. Developer information may also be extremely helpful, such as when organizations respond to vulnerabilities in commercial off-the-shelf products.', 'kb-doc-14-nist-sp-800-53-p310-12', 0, 42, '14-nist-sp-800-53', 'retrieved', '18632AE2BD12B462439E24712935C545FAAC1F5615C9A938A659BAD22417E454', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
