INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p310-14', 'doc-14-nist-sp-800-53', '', 310, '(11) DEVELOPMENT PROCESS, STANDARDS, AND TOOLS | ARCHIVE SYSTEM OR COMPONENT Require the developer of the system or system component to archive the system or component to be released or delivered together with the corresponding evidence supporting the final security and privacy review.', 'kb-doc-14-nist-sp-800-53-p310-14', 0, 43, '14-nist-sp-800-53', 'retrieved', '19608CC4602FB693925D1AC51F6045F3B419830422939E6A2CA166FBE2C8BF25', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
