VALUES ('doc-14-nist-sp-800-53-p313-10', 'doc-14-nist-sp-800-53', '', 313, '(5) DEVELOPER SECURITY AND PRIVACY ARCHITECTURE AND DESIGN | CONCEPTUALLY SIMPLE DESIGN Require the developer of the system, system component, or system service to:', 'kb-doc-14-nist-sp-800-53-p313-10', 0, 24, '14-nist-sp-800-53', 'retrieved', '3AE2898536744B9DEB414EBA6877077C513042A534EBA5E2E3B95CEB3DB7CE85', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
