VALUES ('doc-14-nist-sp-800-53-p314-1', 'doc-14-nist-sp-800-53', '', 314, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 287 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p314-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '00717F286F6CFC0097D1698A744EFCB8340C9061475A7C7A67866484C814F3BE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
