INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p314-2', 'doc-14-nist-sp-800-53', '', 314, '(a) Design and structure the security-relevant hardware, software, and firmware to use a complete, conceptually simple protection mechanism with precisely defined semantics; and (b) Internally structure the security-relevant hardware, software, and firmware with specific regard for this mechanism.', 'kb-doc-14-nist-sp-800-53-p314-2', 0, 38, '14-nist-sp-800-53', 'retrieved', '1155015A628C4084B2182D31BAD04D630E784FEA3E01BF7376DBF42D4B2967FA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
