VALUES ('doc-14-nist-sp-800-53-p316-1', 'doc-14-nist-sp-800-53', '', 316, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 289 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p316-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C81AC451D47B69FD27C23A179E24AF61A342185DBE80BDA1FA2BC1C077E2E9D8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
