VALUES ('doc-14-nist-sp-800-53-p317-1', 'doc-14-nist-sp-800-53', '', 317, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 290 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p317-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D7415565797B8A18072B2469718E8CD5B1D7A44F0104A91CFD3B92DD14422210', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
