VALUES ('doc-14-nist-sp-800-53-p317-5', 'doc-14-nist-sp-800-53', '', 317, 'Control Enhancements: (1) DEVELOPER SCREENING | VALIDATION OF SCREENING [Withdrawn: Incorporated into SA-21.] References: None.', 'kb-doc-14-nist-sp-800-53-p317-5', 0, 15, '14-nist-sp-800-53', 'retrieved', 'AD50C39BD1C5F9901F693E177EA37D1825A993A8E31CD3022C9A00ED056CC3A4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
