VALUES ('doc-14-nist-sp-800-53-p317-11', 'doc-14-nist-sp-800-53', '', 317, 'Control Enhancements: (1) UNSUPPORTED SYSTEM COMPONENTS | ALTERNATIVE SOURCES FOR CONTINUED SUPPORT [Withdrawn: Incorporated into SA-22.] References: None.', 'kb-doc-14-nist-sp-800-53-p317-11', 0, 18, '14-nist-sp-800-53', 'retrieved', 'CD3DB3BA72A2365020E446968557F5BD4F78E3E7AAEC771BA3F3AD0940375DCC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
