VALUES ('doc-14-nist-sp-800-53-p318-1', 'doc-14-nist-sp-800-53', '', 318, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 291 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p318-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '7AEFD11F324F8F28E8E5ECA5D545879E0F05F23E2715F74A45F1C457519BDC3C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
