VALUES ('doc-14-nist-sp-800-53-p319-1', 'doc-14-nist-sp-800-53', '', 319, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 292 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p319-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '64C5651E7A0F27655F7E6539F4D61392ED122E3AB1AF0A633BCE4B6C5A8620EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
