VALUES ('doc-14-nist-sp-800-53-p320-2', 'doc-14-nist-sp-800-53', '', 320, 'SC-2 SEPARATION OF SYSTEM AND USER FUNCTIONALITY Control: Separate user functionality, including user interface services, from system management functionality.', 'kb-doc-14-nist-sp-800-53-p320-2', 0, 19, '14-nist-sp-800-53', 'retrieved', 'DE45785E73685844FF4C12A13F542B5A1C55F3CD9A7F55080C5EE9CDD636F61F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
