INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p321-3', 'doc-14-nist-sp-800-53', '', 321, 'Related Controls: AC-3, AC-6, AC-25, CM-2, CM-4, SA-4, SA-5, SA-8, SA-15, SA-17, SC-2, SC-7, SC- 32, SC-39, SI-16.', 'kb-doc-14-nist-sp-800-53-p321-3', 0, 18, '14-nist-sp-800-53', 'retrieved', '996A38FE820504F964D8A4C23B24CD0D1E406DA4936853D09C626710D6B06DCA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
