VALUES ('doc-14-nist-sp-800-53-p322-1', 'doc-14-nist-sp-800-53', '', 322, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 295 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p322-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0247049B46772875B41873532F933B2C513A933776912024405CDF014B1A63B4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
