INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p322-5', 'doc-14-nist-sp-800-53', '', 322, 'Discussion: The implementation of layered structures with minimized interactions among security functions and non-looping layers (i.e., lower-layer functions do not depend on higher-layer functions) enables the isolation of security functions and the management of complexity.', 'kb-doc-14-nist-sp-800-53-p322-5', 0, 35, '14-nist-sp-800-53', 'retrieved', 'D2E286A9C720C46802F9C2BD04CC2C6476909E2F03AD1E2F54A6EDCBD2F7C018', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p322-8', 'doc-14-nist-sp-800-53', '', 322, 'SC-4 INFORMATION IN SHARED SYSTEM RESOURCES Control: Prevent unauthorized and unintended information transfer via shared system resources.', 'kb-doc-14-nist-sp-800-53-p322-8', 0, 17, '14-nist-sp-800-53', 'retrieved', 'E31982C7DA6B5393008F64609F9443A58ACF733E8A068F40F760E78EFC671F4C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p322-9', 'doc-14-nist-sp-800-53', '', 322, 'Discussion: Preventing unauthorized and unintended information transfer via shared system resources stops information produced by the actions of prior users or roles (or the actions of processes acting on behalf of prior users or roles) from being available to current users or roles (or current processes acting on behalf of current users or roles) that obtain access to shared system resources after those resources have been released back to the system. Information in shared system resources also applies to encrypted representations of information. In other contexts, control of information in shared system resources is referred to as object reuse and residual information protection. Information in shared system resources does not address information remanence, which refers to the residual representation of data that has been nominally deleted; covert channels (including storage and timing channels), where shared system resources are manipulated to violate information flow restrictions; or components within systems for which there are only single users or roles.', 'kb-doc-14-nist-sp-800-53-p322-9', 0, 157, '14-nist-sp-800-53', 'retrieved', 'A3E1AAEBEAE5E85A63F17919BCDE78AA4C478F7295313C21FD3FFB896C5B2C84', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p322-11', 'doc-14-nist-sp-800-53', '', 322, 'Control Enhancements: (1) INFORMATION IN SHARED SYSTEM RESOURCES | SECURITY LEVELS [Withdrawn: Incorporated into SC-4.] (2) INFORMATION IN SHARED SYSTEM RESOURCES | MULTILEVEL OR PERIODS PROCESSING Prevent unauthorized information transfer via shared resources in accordance with [Assignment: organization-defined procedures] when system processing explicitly switches between different information classification levels or security categories.', 'kb-doc-14-nist-sp-800-53-p322-11', 0, 52, '14-nist-sp-800-53', 'retrieved', '4ED7BB18BFEB3E7995914591A1BE14D10E995A22686758E0DEE45795A0957EC7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p322-12', 'doc-14-nist-sp-800-53', '', 322, 'Discussion: Changes in processing levels can occur during multilevel or periods processing with information at different classification levels or security categories. It can also occur during serial reuse of hardware components at different classification levels. Organization- defined procedures can include approved sanitization processes for electronically stored information.', 'kb-doc-14-nist-sp-800-53-p322-12', 0, 47, '14-nist-sp-800-53', 'retrieved', '64E98B06E2C67D623850FB73DD18B0131D9CFA267289FD7C67392CF3192343B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p323-1', 'doc-14-nist-sp-800-53', '', 323, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 296 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p323-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '6E34F9A9A4393610E3CE660DE3C1AC4E9EA07E182AF59D7538167013BCDA89C6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
