VALUES ('doc-14-nist-sp-800-53-p325-1', 'doc-14-nist-sp-800-53', '', 325, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 298 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p325-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '7150C08D81C2630525B08608C151AB3DE4D2932E1633BEE14D4B49EFAF1483AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
