INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-3', 'doc-14-nist-sp-800-53', '', 325, 'Control Enhancements: (1) BOUNDARY PROTECTION | PHYSICALLY SEPARATED SUBNETWORKS [Withdrawn: Incorporated into SC-7.] (2) BOUNDARY PROTECTION | PUBLIC ACCESS [Withdrawn: Incorporated into SC-7.] (3) BOUNDARY PROTECTION | ACCESS POINTS Limit the number of external network connections to the system.', 'kb-doc-14-nist-sp-800-53-p325-3', 0, 39, '14-nist-sp-800-53', 'retrieved', 'A55FF9EEA76677CB78C3B645239E076404D7D7631BB41B96129E2E47A21D7D0A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-4', 'doc-14-nist-sp-800-53', '', 325, 'Discussion: Limiting the number of external network connections facilitates monitoring of inbound and outbound communications traffic. The Trusted Internet Connection [DHS TIC] initiative is an example of a federal guideline that requires limits on the number of external network connections. Limiting the number of external network connections to the system is important during transition periods from older to newer technologies (e.g., transitioning from IPv4 to IPv6 network protocols). Such transitions may require implementing the older and newer technologies simultaneously during the transition period and thus increase the number of access points to the system.', 'kb-doc-14-nist-sp-800-53-p325-4', 0, 94, '14-nist-sp-800-53', 'retrieved', 'C5F25419E0F8C3DD859A5CD45ECCC6AC78CC640E7E593342975ECA5B0B27D418', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-6', 'doc-14-nist-sp-800-53', '', 325, '(4) BOUNDARY PROTECTION | EXTERNAL TELECOMMUNICATIONS SERVICES (a) Implement a managed interface for each external telecommunication service; (b) Establish a traffic flow policy for each managed interface; (c) Protect the confidentiality and integrity of the information being transmitted across each interface; (d) Document each exception to the traffic flow policy with a supporting mission or business need and duration of that need; (e) Review exceptions to the traffic flow policy [Assignment: organization-defined frequency] and remove exceptions that are no longer supported by an explicit mission or business need; (f) Prevent unauthorized exchange of control plane traffic with external networks; (g) Publish information to enable remote networks to detect unauthorized control plane traffic from internal networks; and (h) Filter unauthorized control plane traffic from external networks.', 'kb-doc-14-nist-sp-800-53-p325-6', 0, 125, '14-nist-sp-800-53', 'retrieved', '4E14B0D3831D3EB41A0D4B1896FED7D9486BB17BE86B6D266DE6E8C245CC6F2A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-7', 'doc-14-nist-sp-800-53', '', 325, 'Discussion: External telecommunications services can provide data and/or voice communications services. Examples of control plane traffic include Border Gateway Protocol (BGP) routing, Domain Name System (DNS), and management protocols. See [SP 800-189] for additional information on the use of the resource public key infrastructure (RPKI) to protect BGP routes and detect unauthorized BGP announcements.', 'kb-doc-14-nist-sp-800-53-p325-7', 0, 54, '14-nist-sp-800-53', 'retrieved', 'BC5D02990C7E59C9820DA69296C04BC62FAE3B47C4C99BCECA8809E86DC02712', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-9', 'doc-14-nist-sp-800-53', '', 325, '(5) BOUNDARY PROTECTION | DENY BY DEFAULT — ALLOW BY EXCEPTION Deny network communications traffic by default and allow network communications traffic by exception [Selection (one or more): at managed interfaces; for [Assignment: organization-defined systems]].', 'kb-doc-14-nist-sp-800-53-p325-9', 0, 35, '14-nist-sp-800-53', 'retrieved', 'B2C4E1F38E532914FD4F9E3D7210BF840DB39C8F41ED6B89A234F764DEEDCACE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
