INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p325-10', 'doc-14-nist-sp-800-53', '', 325, 'Discussion: Denying by default and allowing by exception applies to inbound and outbound network communications traffic. A deny-all, permit-by-exception network communications traffic policy ensures that only those system connections that are essential and approved are', 'kb-doc-14-nist-sp-800-53-p325-10', 0, 35, '14-nist-sp-800-53', 'retrieved', '1B23BD6C0B38E70207BF5E5B1BEE34A24D3A9E4D8DC6FDA79EAB665CAC91C878', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
