INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p326-2', 'doc-14-nist-sp-800-53', '', 326, 'allowed. Deny by default, allow by exception also applies to a system that is connected to an external system.', 'kb-doc-14-nist-sp-800-53-p326-2', 0, 19, '14-nist-sp-800-53', 'retrieved', 'AA488A7427D043CE6AD1AA0F2205A3FFFEF550D08160DFFFBEBFB818C2301606', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
