INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p327-2', 'doc-14-nist-sp-800-53', '', 327, 'incoming and outgoing communications traffic while searching for indications of internal threats to the security of external systems. Internal threats to external systems include traffic indicative of denial-of-service attacks, traffic with spoofed source addresses, and traffic that contains malicious code. Organizations have criteria to determine, update, and manage identified threats related to extrusion detection.', 'kb-doc-14-nist-sp-800-53-p327-2', 0, 54, '14-nist-sp-800-53', 'retrieved', '9D2D97B4C15875EABC21E9740242C0F26EB4B44F4B61CFC6597EFD1DB547C492', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
