VALUES ('doc-14-nist-sp-800-53-p327-12', 'doc-14-nist-sp-800-53', '', 327, 'System components that employ host-based boundary protection mechanisms include servers, workstations, notebook computers, and mobile devices.', 'kb-doc-14-nist-sp-800-53-p327-12', 0, 16, '14-nist-sp-800-53', 'retrieved', '1B995B57F4D9C38C4B86C5304D952F52BE1D63CCFA5FFA720A29E3FFEF6132CC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
