VALUES ('doc-14-nist-sp-800-53-p328-1', 'doc-14-nist-sp-800-53', '', 328, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 301 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p328-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '87DD8A1B17DE4DC6A94267084AB38F7581064DEE909A982833BDEF97CCE829E8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
