INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-5', 'doc-14-nist-sp-800-53', '', 328, '(14) BOUNDARY PROTECTION | PROTECT AGAINST UNAUTHORIZED PHYSICAL CONNECTIONS Protect against unauthorized physical connections at [Assignment: organization-defined managed interfaces].', 'kb-doc-14-nist-sp-800-53-p328-5', 0, 19, '14-nist-sp-800-53', 'retrieved', '6D65E2687D6DBDBA371F70214DA6BB499B9C5B7C79419C36B95A4A7C57A6737B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-6', 'doc-14-nist-sp-800-53', '', 328, 'Discussion: Systems that operate at different security categories or classification levels may share common physical and environmental controls, since the systems may share space within the same facilities. In practice, it is possible that these separate systems may share common equipment rooms, wiring closets, and cable distribution paths. Protection against unauthorized physical connections can be achieved by using clearly identified and physically separated cable trays, connection frames, and patch panels for each side of managed interfaces with physical access controls that enforce limited authorized access to these items.', 'kb-doc-14-nist-sp-800-53-p328-6', 0, 88, '14-nist-sp-800-53', 'retrieved', 'C7B2C7B3A290E7868B6A59FF54EAAC1C3770672CDFB164ACADF497B1ECB384BF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-8', 'doc-14-nist-sp-800-53', '', 328, '(15) BOUNDARY PROTECTION | NETWORKED PRIVILEGED ACCESSES Route networked, privileged accesses through a dedicated, managed interface for purposes of access control and auditing.', 'kb-doc-14-nist-sp-800-53-p328-8', 0, 23, '14-nist-sp-800-53', 'retrieved', '8ED78622542FC94A3D89473EF45D78E2CB63963EBD73CF21DFF3C2082128F25B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-9', 'doc-14-nist-sp-800-53', '', 328, 'Discussion: Privileged access provides greater accessibility to system functions, including security functions. Adversaries attempt to gain privileged access to systems through remote access to cause adverse mission or business impacts, such as by exfiltrating information or bringing down a critical system capability. Routing networked, privileged access requests through a dedicated, managed interface further restricts privileged access for increased access control and auditing.', 'kb-doc-14-nist-sp-800-53-p328-9', 0, 62, '14-nist-sp-800-53', 'retrieved', '963E03C12A8C1C3B413FEF3E4B9BC3616B35261CDCC99BBA4B61A3DF08C99780', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-11', 'doc-14-nist-sp-800-53', '', 328, '(16) BOUNDARY PROTECTION | PREVENT DISCOVERY OF SYSTEM COMPONENTS Prevent the discovery of specific system components that represent a managed interface.', 'kb-doc-14-nist-sp-800-53-p328-11', 0, 21, '14-nist-sp-800-53', 'retrieved', 'D4B1E2F0A6F845D8C16BAEBB270EA9E5298BC75BD4BB7A8B32CE519C9A4589D9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-12', 'doc-14-nist-sp-800-53', '', 328, 'Discussion: Preventing the discovery of system components representing a managed interface helps protect network addresses of those components from discovery through common tools and techniques used to identify devices on networks. Network addresses are not available for discovery and require prior knowledge for access. Preventing the discovery of components and devices can be accomplished by not publishing network addresses, using network address translation, or not entering the addresses in domain name systems.', 'kb-doc-14-nist-sp-800-53-p328-12', 0, 72, '14-nist-sp-800-53', 'retrieved', '9A1F99B23E3FF57931ADEB9F742DDA9682CB92A93A6A5D33C73F12A41DE34DD5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
