VALUES ('doc-14-nist-sp-800-53-p328-15', 'doc-14-nist-sp-800-53', '', 328, '(17) BOUNDARY PROTECTION | AUTOMATED ENFORCEMENT OF PROTOCOL FORMATS Enforce adherence to protocol formats.', 'kb-doc-14-nist-sp-800-53-p328-15', 0, 14, '14-nist-sp-800-53', 'retrieved', 'E68E75D725974638C4056E853136D3021AD57B1E872A25740376DEE5A9C0EFB6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
