INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p328-16', 'doc-14-nist-sp-800-53', '', 328, 'Discussion: System components that enforce protocol formats include deep packet inspection firewalls and XML gateways. The components verify adherence to protocol', 'kb-doc-14-nist-sp-800-53-p328-16', 0, 21, '14-nist-sp-800-53', 'retrieved', 'CAC7719E625A202C5041AC8181F8EC3F250B0A5B269EEBA82E83FC5409D6EF23', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
