VALUES ('doc-14-nist-sp-800-53-p329-1', 'doc-14-nist-sp-800-53', '', 329, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 302 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p329-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '63E018D22EF88D5251602115518F2D9BFAFBCDBCBE5937DE5F1096ADE57BA48A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
