VALUES ('doc-14-nist-sp-800-53-p329-2', 'doc-14-nist-sp-800-53', '', 329, 'formats and specifications at the application layer and identify vulnerabilities that cannot be detected by devices operating at the network or transport layers.', 'kb-doc-14-nist-sp-800-53-p329-2', 0, 23, '14-nist-sp-800-53', 'retrieved', 'A48554D1227C3EE72B704ADB0AF370CB95DCAF2E2B50D73B2919B2D470FC730C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
