VALUES ('doc-14-nist-sp-800-53-p330-2', 'doc-14-nist-sp-800-53', '', 330, 'that separate subnetworks; virtualization techniques; and the encryption of information flows among system components using distinct encryption keys.', 'kb-doc-14-nist-sp-800-53-p330-2', 0, 18, '14-nist-sp-800-53', 'retrieved', '4E1C06EAD91FC9FF598CDFDB432D3D65E3DCC71F5CF5C547F6A71CA4C5A4A332', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
