VALUES ('doc-14-nist-sp-800-53-p330-4', 'doc-14-nist-sp-800-53', '', 330, '(22) BOUNDARY PROTECTION | SEPARATE SUBNETS FOR CONNECTING TO DIFFERENT SECURITY DOMAINS Implement separate network addresses to connect to systems in different security domains.', 'kb-doc-14-nist-sp-800-53-p330-4', 0, 24, '14-nist-sp-800-53', 'retrieved', '29580DD12DE4591901E47C75E58A8DCD87E39864668DE0978368BD90DB83F2BD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
