INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p330-5', 'doc-14-nist-sp-800-53', '', 330, 'Discussion: The decomposition of systems into subnetworks (i.e., subnets) helps to provide the appropriate level of protection for network connections to different security domains that contain information with different security categories or classification levels.', 'kb-doc-14-nist-sp-800-53-p330-5', 0, 34, '14-nist-sp-800-53', 'retrieved', 'BF6AA8BF4A6FFDA24DD38BA8C726B24F605554B62AF23FE789C2F116B65F3CAB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
