VALUES ('doc-14-nist-sp-800-53-p330-7', 'doc-14-nist-sp-800-53', '', 330, '(23) BOUNDARY PROTECTION | DISABLE SENDER FEEDBACK ON PROTOCOL VALIDATION FAILURE Disable feedback to senders on protocol format validation failure.', 'kb-doc-14-nist-sp-800-53-p330-7', 0, 20, '14-nist-sp-800-53', 'retrieved', 'CD991D23A734AF87BBA8E45CBCE4AD85CAB243FC9D776222840D4198B7081353', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
