INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p330-8', 'doc-14-nist-sp-800-53', '', 330, 'Discussion: Disabling feedback to senders when there is a failure in protocol validation format prevents adversaries from obtaining information that would otherwise be unavailable.', 'kb-doc-14-nist-sp-800-53-p330-8', 0, 24, '14-nist-sp-800-53', 'retrieved', 'A7502F4369C90BB5CDA669BAA0E82D82B8715630C06C484F0465B5B8BB980B70', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
