VALUES ('doc-14-nist-sp-800-53-p331-1', 'doc-14-nist-sp-800-53', '', 331, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 304 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p331-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0E7AEC9E52D8ED30941D4E6C7C7C06C85124A201624DEE6CD7F436F5B117047A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
