VALUES ('doc-14-nist-sp-800-53-p331-7', 'doc-14-nist-sp-800-53', '', 331, '(28) BOUNDARY PROTECTION | CONNECTIONS TO PUBLIC NETWORKS Prohibit the direct connection of [Assignment: organization-defined system] to a public network.', 'kb-doc-14-nist-sp-800-53-p331-7', 0, 20, '14-nist-sp-800-53', 'retrieved', 'ED7900620CAA37AE00264694C4F74332D8E156BB21639AB1566B44CFD7D49B64', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
