INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p331-8', 'doc-14-nist-sp-800-53', '', 331, 'Discussion: A direct connection is a dedicated physical or virtual connection between two or more systems. A public network is a network accessible to the public, including the Internet and organizational extranets with public access.', 'kb-doc-14-nist-sp-800-53-p331-8', 0, 35, '14-nist-sp-800-53', 'retrieved', 'E844B61DE7622EA586575D848C2E1A87D02C675D05FE318CA61CF70C9EA46863', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
