VALUES ('doc-14-nist-sp-800-53-p331-14', 'doc-14-nist-sp-800-53', '', 331, 'SC-8 TRANSMISSION CONFIDENTIALITY AND INTEGRITY Control: Protect the [Selection (one or more): confidentiality; integrity] of transmitted information.', 'kb-doc-14-nist-sp-800-53-p331-14', 0, 17, '14-nist-sp-800-53', 'retrieved', '8297D16BDBBA24C5808F0F1F2D9B74BB216EB648B0817CFF2810680708917777', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
