VALUES ('doc-14-nist-sp-800-53-p333-1', 'doc-14-nist-sp-800-53', '', 333, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 306 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p333-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '73A35288F44AF4C4E9A5B8C033CAE422C7FC78D75A2F5EA87BDC81FF10A8E401', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
