INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p333-6', 'doc-14-nist-sp-800-53', '', 333, 'Discussion: The purpose of a protected distribution system is to deter, detect, and/or make difficult physical access to the communication lines that carry national security information.', 'kb-doc-14-nist-sp-800-53-p333-6', 0, 26, '14-nist-sp-800-53', 'retrieved', '450F1A7382FCF0FC88AD9958591C16675CED66C0F9A039C87DCDC0C55B766636', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
