VALUES ('doc-14-nist-sp-800-53-p333-8', 'doc-14-nist-sp-800-53', '', 333, 'References: [FIPS 140-3], [FIPS 197], [SP 800-52], [SP 800-77], [SP 800-81-2], [SP 800-113], [SP 800-177], [IR 8023].', 'kb-doc-14-nist-sp-800-53-p333-8', 0, 17, '14-nist-sp-800-53', 'retrieved', 'AB3711DD005A40DC758A70E189CAFF21543C438A27E29A6318BC32C03776710F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
