INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p333-9', 'doc-14-nist-sp-800-53', '', 333, 'SC-9 TRANSMISSION CONFIDENTIALITY [Withdrawn: Incorporated into SC-8.] SC-10 NETWORK DISCONNECT Control: Terminate the network connection associated with a communications session at the end of the session or after [Assignment: organization-defined time period] of inactivity.', 'kb-doc-14-nist-sp-800-53-p333-9', 0, 34, '14-nist-sp-800-53', 'retrieved', '92DDB8FF2753226B0674F5CCB7F726367C4FB40DE8864448A3EC1272EF494405', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p333-10', 'doc-14-nist-sp-800-53', '', 333, 'Discussion: Network disconnect applies to internal and external networks. Terminating network connections associated with specific communications sessions includes de-allocating TCP/IP address or port pairs at the operating system level and de-allocating the networking assignments at the application level if multiple application sessions are using a single operating system-level network connection. Periods of inactivity may be established by organizations and include time periods by type of network access or for specific network accesses.', 'kb-doc-14-nist-sp-800-53-p333-10', 0, 72, '14-nist-sp-800-53', 'retrieved', 'AE77CCED04DE5005E0B845FA46F1382E651E3DF6FB11F6CDE9C9DF8A3AFF71DD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
