VALUES ('doc-14-nist-sp-800-53-p334-12', 'doc-14-nist-sp-800-53', '', 334, 'Related Controls: AC-17, AU-9, AU-10, CM-3, IA-3, IA-7, SA-4, SA-8, SA-9, SC-8, SC-11, SC-12, SC- 13, SC-17, SC-20, SC-37, SC-40, SI-3, SI-7.', 'kb-doc-14-nist-sp-800-53-p334-12', 0, 22, '14-nist-sp-800-53', 'retrieved', '8F0447336675867CFC88D1F04E674695A0969BAFC61F1E1120658001FFE08D9A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
