VALUES ('doc-14-nist-sp-800-53-p335-1', 'doc-14-nist-sp-800-53', '', 335, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 308 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p335-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '317041DA2BE0DB42CDB171B7B415A05C418F2A1C37D129487A45667144A0FBD1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
