INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p335-2', 'doc-14-nist-sp-800-53', '', 335, 'Control Enhancements: (1) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | AVAILABILITY Maintain availability of information in the event of the loss of cryptographic keys by users.', 'kb-doc-14-nist-sp-800-53-p335-2', 0, 25, '14-nist-sp-800-53', 'retrieved', '65EAF598DCB40675541EF75503EE0632016AB9DC87D9E99802BC89EAFDD61F6B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p335-3', 'doc-14-nist-sp-800-53', '', 335, 'Discussion: Escrowing of encryption keys is a common practice for ensuring availability in the event of key loss. A forgotten passphrase is an example of losing a cryptographic key.', 'kb-doc-14-nist-sp-800-53-p335-3', 0, 29, '14-nist-sp-800-53', 'retrieved', '893CCE2B673FCCFF39FCD1DA4AE025528527ADB646F5123A7B769756D36E513E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
