INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p335-5', 'doc-14-nist-sp-800-53', '', 335, '(2) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | SYMMETRIC KEYS Produce, control, and distribute symmetric cryptographic keys using [Selection: NIST FIPS- validated; NSA-approved] key management technology and processes.', 'kb-doc-14-nist-sp-800-53-p335-5', 0, 27, '14-nist-sp-800-53', 'retrieved', '91A707A4A16EB9020A78C5740EA9EC8FEC9E6C87BD60F341E499D208EBB4E828', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
