INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p335-11', 'doc-14-nist-sp-800-53', '', 335, '(4) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PKI CERTIFICATES [Withdrawn: Incorporated into SC-12(3).] (5) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PKI CERTIFICATES / HARDWARE TOKENS [Withdrawn: Incorporated into SC-12(3).] (6) CRYPTOGRAPHIC KEY ESTABLISHMENT AND MANAGEMENT | PHYSICAL CONTROL OF KEYS Maintain physical control of cryptographic keys when stored information is encrypted by external service providers.', 'kb-doc-14-nist-sp-800-53-p335-11', 0, 55, '14-nist-sp-800-53', 'retrieved', 'E978E98A0F5CF147A141210FBC8C47DAE67F582769FF064B5BA544EA961C8C3B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
