INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p335-12', 'doc-14-nist-sp-800-53', '', 335, 'Discussion: For organizations that use external service providers (e.g., cloud service or data center providers), physical control of cryptographic keys provides additional assurance that information stored by such external providers is not subject to unauthorized disclosure or modification.', 'kb-doc-14-nist-sp-800-53-p335-12', 0, 38, '14-nist-sp-800-53', 'retrieved', '43BFF64ECA2C2E03AE1EA8A389635F88575177706611F8B55DEAB451D21F792A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
