VALUES ('doc-14-nist-sp-800-53-p336-1', 'doc-14-nist-sp-800-53', '', 336, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 309 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p336-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C08C01F64716C75E5677853E9BC34624E55E0A077DA14343E581AE6C2D3E76FD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
