INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p336-2', 'doc-14-nist-sp-800-53', '', 336, 'b. Implement the following types of cryptography required for each specified cryptographic use: [Assignment: organization-defined types of cryptography for each specified cryptographic use].', 'kb-doc-14-nist-sp-800-53-p336-2', 0, 23, '14-nist-sp-800-53', 'retrieved', '308D311B3890BDC043CECAF43078D83DCD216FB7A4D18F84AAE566FE6A20CAB5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
