INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p336-3', 'doc-14-nist-sp-800-53', '', 336, 'Discussion: Cryptography can be employed to support a variety of security solutions, including the protection of classified information and controlled unclassified information, the provision and implementation of digital signatures, and the enforcement of information separation when authorized individuals have the necessary clearances but lack the necessary formal access approvals. Cryptography can also be used to support random number and hash generation.', 'kb-doc-14-nist-sp-800-53-p336-3', 0, 61, '14-nist-sp-800-53', 'retrieved', 'CD90C73D5905AEEA4A94CB58E6FC99B3665CF7E28A17A1734F3297A29FFCE97A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p336-4', 'doc-14-nist-sp-800-53', '', 336, 'Generally applicable cryptographic standards include FIPS-validated cryptography and NSA- approved cryptography. For example, organizations that need to protect classified information may specify the use of NSA-approved cryptography. Organizations that need to provision and implement digital signatures may specify the use of FIPS-validated cryptography. Cryptography is implemented in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p336-4', 0, 59, '14-nist-sp-800-53', 'retrieved', '131B81AF25BAC53EBE8EBDE05938F8E9A39D75E5ED7357EA2A3AEE2682D0AA13', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
