VALUES ('doc-14-nist-sp-800-53-p336-7', 'doc-14-nist-sp-800-53', '', 336, '(1) CRYPTOGRAPHIC PROTECTION | FIPS-VALIDATED CRYPTOGRAPHY [Withdrawn: Incorporated into SC-13.] (2) CRYPTOGRAPHIC PROTECTION | NSA-APPROVED CRYPTOGRAPHY [Withdrawn: Incorporated into SC-13.] (3) CRYPTOGRAPHIC PROTECTION | INDIVIDUALS WITHOUT FORMAL ACCESS APPROVALS [Withdrawn: Incorporated into SC-13.] (4) CRYPTOGRAPHIC PROTECTION | DIGITAL SIGNATURES [Withdrawn: Incorporated into SC-13.] References: [FIPS 140-3].', 'kb-doc-14-nist-sp-800-53-p336-7', 0, 46, '14-nist-sp-800-53', 'retrieved', 'D317A3657DF6F5EF8C73D4A6A5DA81554F060B383A8CD30C5B58813C0895EEF5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
