INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p336-8', 'doc-14-nist-sp-800-53', '', 336, 'SC-14 PUBLIC ACCESS PROTECTIONS [Withdrawn: Incorporated into AC-2, AC-3, AC-5, AC-6, SI-3, SI-4, SI-5, SI-7, and SI-10.] SC-15 COLLABORATIVE COMPUTING DEVICES AND APPLICATIONS Control: a. Prohibit remote activation of collaborative computing devices and applications with the following exceptions: [Assignment: organization-defined exceptions where remote activation is to be allowed]; and b. Provide an explicit indication of use to users physically present at the devices.', 'kb-doc-14-nist-sp-800-53-p336-8', 0, 63, '14-nist-sp-800-53', 'retrieved', '84952EDB087DCAADA8C3DC76A3EA607F277F526AF8A91E9095DDA794B161E4EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
