INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p336-9', 'doc-14-nist-sp-800-53', '', 336, 'Discussion: Collaborative computing devices and applications include remote meeting devices and applications, networked white boards, cameras, and microphones. The explicit indication of use includes signals to users when collaborative computing devices and applications are activated.', 'kb-doc-14-nist-sp-800-53-p336-9', 0, 35, '14-nist-sp-800-53', 'retrieved', '55EC087A753F41154E500068C2E79B0A0F78DD62D9DFF3479E602FA96AEBE055', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
