INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-2', 'doc-14-nist-sp-800-53', '', 337, '(1) COLLABORATIVE COMPUTING DEVICES | PHYSICAL OR LOGICAL DISCONNECT Provide [Selection (one or more): physical; logical] disconnect of collaborative computing devices in a manner that supports ease of use.', 'kb-doc-14-nist-sp-800-53-p337-2', 0, 29, '14-nist-sp-800-53', 'retrieved', '37E9639B3942B8967F16E3033276C94EC32244648B846CFBF1ED4FF4D2BD395C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-3', 'doc-14-nist-sp-800-53', '', 337, 'Discussion: Failing to disconnect from collaborative computing devices can result in subsequent compromises of organizational information. Providing easy methods to disconnect from such devices after a collaborative computing session ensures that participants carry out the disconnect activity without having to go through complex and tedious procedures. Disconnect from collaborative computing devices can be manual or automatic.', 'kb-doc-14-nist-sp-800-53-p337-3', 0, 56, '14-nist-sp-800-53', 'retrieved', 'A2DBEE4633E61C15331AAA4BCE69EED8C6A0F7C100471B5CCC339688D767A801', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-5', 'doc-14-nist-sp-800-53', '', 337, '(2) COLLABORATIVE COMPUTING DEVICES | BLOCKING INBOUND AND OUTBOUND COMMUNICATIONS TRAFFIC [Withdrawn: Incorporated into SC-7.] (3) COLLABORATIVE COMPUTING DEVICES | DISABLING AND REMOVAL IN SECURE WORK AREAS Disable or remove collaborative computing devices and applications from [Assignment: organization-defined systems or system components] in [Assignment: organization-defined secure work areas].', 'kb-doc-14-nist-sp-800-53-p337-5', 0, 48, '14-nist-sp-800-53', 'retrieved', 'BD163F252D28EE6C9FB1C95A83C138DA8D07B4F68A3C0E1244D597338F2DE663', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-6', 'doc-14-nist-sp-800-53', '', 337, 'Discussion: Failing to disable or remove collaborative computing devices and applications from systems or system components can result in compromises of information, including eavesdropping on conversations. A Sensitive Compartmented Information Facility (SCIF) is an example of a secure work area.', 'kb-doc-14-nist-sp-800-53-p337-6', 0, 40, '14-nist-sp-800-53', 'retrieved', '70399B607ABD1EC64D70AE20319993017E52163699D2228262198D5A525ED96C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-8', 'doc-14-nist-sp-800-53', '', 337, '(4) COLLABORATIVE COMPUTING DEVICES | EXPLICITLY INDICATE CURRENT PARTICIPANTS Provide an explicit indication of current participants in [Assignment: organization-defined online meetings and teleconferences].', 'kb-doc-14-nist-sp-800-53-p337-8', 0, 23, '14-nist-sp-800-53', 'retrieved', '28344CF69A90E2F91DE0219D6923CC586DFAD58C57E3748434EE3572DD605C00', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p337-9', 'doc-14-nist-sp-800-53', '', 337, 'Discussion: Explicitly indicating current participants prevents unauthorized individuals from participating in collaborative computing sessions without the explicit knowledge of other participants.', 'kb-doc-14-nist-sp-800-53-p337-9', 0, 21, '14-nist-sp-800-53', 'retrieved', '46D545D2DF35D4C33BDFFCC891A944B6F8ABD318AE64068347B89290EAA60086', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
