INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-2', 'doc-14-nist-sp-800-53', '', 338, '(1) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | INTEGRITY VERIFICATION Verify the integrity of transmitted security and privacy attributes.', 'kb-doc-14-nist-sp-800-53-p338-2', 0, 19, '14-nist-sp-800-53', 'retrieved', 'F7B605992C6884712E40817048912EAFC95FC2EF4C98060F94C7BFD6224436A3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-3', 'doc-14-nist-sp-800-53', '', 338, 'Discussion: Part of verifying the integrity of transmitted information is ensuring that security and privacy attributes that are associated with such information have not been modified in an unauthorized manner. Unauthorized modification of security or privacy attributes can result in a loss of integrity for transmitted information.', 'kb-doc-14-nist-sp-800-53-p338-3', 0, 47, '14-nist-sp-800-53', 'retrieved', '370D3655A6D6C17A0A9B83877241070DA78AF00774074363A55F6A419C7A0F24', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-5', 'doc-14-nist-sp-800-53', '', 338, '(2) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | ANTI-SPOOFING MECHANISMS Implement anti-spoofing mechanisms to prevent adversaries from falsifying the security attributes indicating the successful application of the security process.', 'kb-doc-14-nist-sp-800-53-p338-5', 0, 29, '14-nist-sp-800-53', 'retrieved', '958A1785E6EE1A1637BDF6DF1C0F925479999BE29396CCF34655DF5D89D7A9BA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-6', 'doc-14-nist-sp-800-53', '', 338, 'Discussion: Some attack vectors operate by altering the security attributes of an information system to intentionally and maliciously implement an insufficient level of security within the system. The alteration of attributes leads organizations to believe that a greater number of security functions are in place and operational than have actually been implemented.', 'kb-doc-14-nist-sp-800-53-p338-6', 0, 52, '14-nist-sp-800-53', 'retrieved', 'EF15525B690670527F4B437F83A92525CDF177FDE77C293D551C7D60289A4F1A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-8', 'doc-14-nist-sp-800-53', '', 338, '(3) TRANSMISSION OF SECURITY AND PRIVACY ATTRIBUTES | CRYPTOGRAPHIC BINDING Implement [Assignment: organization-defined mechanisms or techniques] to bind security and privacy attributes to transmitted information.', 'kb-doc-14-nist-sp-800-53-p338-8', 0, 25, '14-nist-sp-800-53', 'retrieved', 'F6D43CD4066E431CBDE7E76573E115B66E7529CE328EDE00A06DF57FBD0D4AD8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p338-9', 'doc-14-nist-sp-800-53', '', 338, 'Discussion: Cryptographic mechanisms and techniques can provide strong security and privacy attribute binding to transmitted information to help ensure the integrity of such information.', 'kb-doc-14-nist-sp-800-53-p338-9', 0, 24, '14-nist-sp-800-53', 'retrieved', '85554D13019B41BFD0CE6EC8F2058A0345BACEFA7434AC36A5D95E9144357FDC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
