INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p339-14', 'doc-14-nist-sp-800-53', '', 339, 'Discussion: Actions enforced before executing mobile code include prompting users prior to opening email attachments or clicking on web links. Preventing the automatic execution of mobile code includes disabling auto-execute features on system components that employ portable storage devices, such as compact discs, digital versatile discs, and universal serial bus devices.', 'kb-doc-14-nist-sp-800-53-p339-14', 0, 51, '14-nist-sp-800-53', 'retrieved', '1596B501E09C93A40E561EFFCB89B8D5283A259E0168D6552998F66E690B2BB5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
