VALUES ('doc-14-nist-sp-800-53-p339-16', 'doc-14-nist-sp-800-53', '', 339, '(5) MOBILE CODE | ALLOW EXECUTION ONLY IN CONFINED ENVIRONMENTS Allow execution of permitted mobile code only in confined virtual machine environments.', 'kb-doc-14-nist-sp-800-53-p339-16', 0, 22, '14-nist-sp-800-53', 'retrieved', '899A68E38FDF74C284A1D1C4CF0AE4EFEFE4BA366A11038064771D6898F22BCD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
