VALUES ('doc-14-nist-sp-800-53-p340-1', 'doc-14-nist-sp-800-53', '', 340, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 313 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p340-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '09464B41FEA5C1B445365AA2D23CB3AA85105A2EF02EF750B9028277C2ACFBA5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
