INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p340-2', 'doc-14-nist-sp-800-53', '', 340, 'Discussion: Permitting the execution of mobile code only in confined virtual machine environments helps prevent the introduction of malicious code into other systems and system components.', 'kb-doc-14-nist-sp-800-53-p340-2', 0, 26, '14-nist-sp-800-53', 'retrieved', 'B604A550C11C00C05CA627FA264CAB1345FAB6667557F66401642E139EC60614', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
