INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p340-5', 'doc-14-nist-sp-800-53', '', 340, 'SC-19 VOICE OVER INTERNET PROTOCOL [Withdrawn: Technology-specific; addressed as any other technology or protocol.] SC-20 SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) Control: a. Provide additional data origin authentication and integrity verification artifacts along with the authoritative name resolution data the system returns in response to external name/address resolution queries; and b. Provide the means to indicate the security status of child zones and (if the child supports secure resolution services) to enable verification of a chain of trust among parent and child domains, when operating as part of a distributed, hierarchical namespace.', 'kb-doc-14-nist-sp-800-53-p340-5', 0, 92, '14-nist-sp-800-53', 'retrieved', '4B4FD522CA73AD3493B7E39DB4CF11C58A09E678246B41FEC9B9E074C0192C0D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
