VALUES ('doc-14-nist-sp-800-53-p340-9', 'doc-14-nist-sp-800-53', '', 340, 'Control Enhancements: (1) SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) | CHILD SUBSPACES [Withdrawn: Incorporated into SC-20.] (2) SECURE NAME/ADDRESS RESOLUTION SERVICE (AUTHORITATIVE SOURCE) | DATA ORIGIN AND INTEGRITY Provide data origin and integrity protection artifacts for internal name/address resolution queries.', 'kb-doc-14-nist-sp-800-53-p340-9', 0, 40, '14-nist-sp-800-53', 'retrieved', '5FCAA541851EB20A3F985C28542698CBDEA6E9CB390F8BB08FC6642DC1C094AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
