VALUES ('doc-14-nist-sp-800-53-p340-13', 'doc-14-nist-sp-800-53', '', 340, 'SC-21 SECURE NAME/ADDRESS RESOLUTION SERVICE (RECURSIVE OR CACHING RESOLVER) Control: Request and perform data origin authentication and data integrity verification on the name/address resolution responses the system receives from authoritative sources.', 'kb-doc-14-nist-sp-800-53-p340-13', 0, 31, '14-nist-sp-800-53', 'retrieved', '61ABFDB4DDF417C181422A687C92D9BA524305E4D93F3A71CADD8840E4F39FD8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
