INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p340-14', 'doc-14-nist-sp-800-53', '', 340, 'Discussion: Each client of name resolution services either performs this validation on its own or has authenticated channels to trusted validation providers. Systems that provide name and', 'kb-doc-14-nist-sp-800-53-p340-14', 0, 27, '14-nist-sp-800-53', 'retrieved', '689B5606F6E10BCFEBB5C2BE14A0857EC78928F5B06E95784F7B8AD42F3E018D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
