VALUES ('doc-14-nist-sp-800-53-p341-5', 'doc-14-nist-sp-800-53', '', 341, '(1) SECURE NAME/ADDRESS RESOLUTION SERVICE (RECURSIVE OR CACHING RESOLVER) | DATA ORIGIN AND INTEGRITY [Withdrawn: Incorporated into SC-21.] References: [SP 800-81-2].', 'kb-doc-14-nist-sp-800-53-p341-5', 0, 21, '14-nist-sp-800-53', 'retrieved', 'A64C805CA025BE39E381357C53C437F5FA8613C72607E13FD6931D6DB3B4C293', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
