VALUES ('doc-14-nist-sp-800-53-p342-1', 'doc-14-nist-sp-800-53', '', 342, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 315 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p342-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '5B01508235C6A9E87CF4AEB643F4A9BD43162438461F0BD16E88E2FAB74D67B7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
