INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p342-15', 'doc-14-nist-sp-800-53', '', 342, 'SC-25 THIN NODES Control: Employ minimal functionality and information storage on the following system components: [Assignment: organization-defined system components].', 'kb-doc-14-nist-sp-800-53-p342-15', 0, 19, '14-nist-sp-800-53', 'retrieved', '4425462868E1DD21CD8452F67F92E8A1DA92F64CA868A360042979AAA3A79A0E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
