VALUES ('doc-14-nist-sp-800-53-p343-1', 'doc-14-nist-sp-800-53', '', 343, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 316 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p343-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '1734EE6280CEBDDA52DB2C655C7B2DEB097C9B1EDAF4063EE054A9627C81F771', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
