INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p343-2', 'doc-14-nist-sp-800-53', '', 343, 'Discussion: The deployment of system components with minimal functionality reduces the need to secure every endpoint and may reduce the exposure of information, systems, and services to attacks. Reduced or minimal functionality includes diskless nodes and thin client technologies.', 'kb-doc-14-nist-sp-800-53-p343-2', 0, 39, '14-nist-sp-800-53', 'retrieved', 'F61FE43ED6B965D543DD20A16075920F55709711EE1E014C39E311E94FD8DCAF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
