INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-3', 'doc-14-nist-sp-800-53', '', 344, 'Related Controls: AC-3, AC-4, AC-6, AC-19, CA-7, CM-3, CM-5, CM-6, CP-9, MP-4, MP-5, PE-3, SC- 8, SC-12, SC-13, SC-34, SI-3, SI-7, SI-16.', 'kb-doc-14-nist-sp-800-53-p344-3', 0, 22, '14-nist-sp-800-53', 'retrieved', 'A62017F69A3B742E611B391068985CD7AB7C8C2F2937076D6E22C2667261BDB7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
