INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-4', 'doc-14-nist-sp-800-53', '', 344, 'Control Enhancements: (1) PROTECTION OF INFORMATION AT REST | CRYPTOGRAPHIC PROTECTION Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of the following information at rest on [Assignment: organization-defined system components or media]: [Assignment: organization-defined information].', 'kb-doc-14-nist-sp-800-53-p344-4', 0, 36, '14-nist-sp-800-53', 'retrieved', '49A7869E66EA63D7A82091A996E90D3A9BB47E53FD395ECDD3F59C373B2C75E8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
