INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-5', 'doc-14-nist-sp-800-53', '', 344, 'Discussion: The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of organizational information. The strength of mechanism is commensurate with the security category or classification of the information. Organizations have the flexibility to encrypt information on system components or media or encrypt data structures, including files, records, or fields.', 'kb-doc-14-nist-sp-800-53-p344-5', 0, 56, '14-nist-sp-800-53', 'retrieved', 'FA9849BB31C37D32B3C2FB856D1B969ACB02CA55AE02282FAF57A84778F43400', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-7', 'doc-14-nist-sp-800-53', '', 344, '(2) PROTECTION OF INFORMATION AT REST | OFFLINE STORAGE Remove the following information from online storage and store offline in a secure location: [Assignment: organization-defined information].', 'kb-doc-14-nist-sp-800-53-p344-7', 0, 26, '14-nist-sp-800-53', 'retrieved', '26C40FC53DE78E3363163ED4C5D4EA249BA41BE49911541A01ECF0015A21ACB9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
