INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-8', 'doc-14-nist-sp-800-53', '', 344, 'Discussion: Removing organizational information from online storage to offline storage eliminates the possibility of individuals gaining unauthorized access to the information through a network. Therefore, organizations may choose to move information to offline storage in lieu of protecting such information in online storage.', 'kb-doc-14-nist-sp-800-53-p344-8', 0, 43, '14-nist-sp-800-53', 'retrieved', 'E810FCCD9834828DA0242B641CC298113BA0A687DCCAC0140149B43804B42D93', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
