INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-10', 'doc-14-nist-sp-800-53', '', 344, '(3) PROTECTION OF INFORMATION AT REST | CRYPTOGRAPHIC KEYS Provide protected storage for cryptographic keys [Selection: [Assignment: organization- defined safeguards]; hardware-protected key store].', 'kb-doc-14-nist-sp-800-53-p344-10', 0, 23, '14-nist-sp-800-53', 'retrieved', '035999FB1E0C9E2E471AAA1FBB977F5B819B7B1B9EC023418A8965A23C53E2D7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
