INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-11', 'doc-14-nist-sp-800-53', '', 344, 'Discussion: A Trusted Platform Module (TPM) is an example of a hardware-protected data store that can be used to protect cryptographic keys.', 'kb-doc-14-nist-sp-800-53-p344-11', 0, 22, '14-nist-sp-800-53', 'retrieved', 'BC266573C460075D5C6EB2B9FD2CBF8143EA1209F5D7FB526401340C6861E9C6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
