INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-14', 'doc-14-nist-sp-800-53', '', 344, 'SC-29 HETEROGENEITY Control: Employ a diverse set of information technologies for the following system components in the implementation of the system: [Assignment: organization-defined system components].', 'kb-doc-14-nist-sp-800-53-p344-14', 0, 25, '14-nist-sp-800-53', 'retrieved', '5E21370C921C0ED8706E7E2B1877C27263C7BE92833DF0689B304E81A7D564A2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
