INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p344-15', 'doc-14-nist-sp-800-53', '', 344, 'Discussion: Increasing the diversity of information technologies within organizational systems reduces the impact of potential exploitations or compromises of specific technologies. Such diversity protects against common mode failures, including those failures induced by supply chain attacks. Diversity in information technologies also reduces the likelihood that the means', 'kb-doc-14-nist-sp-800-53-p344-15', 0, 47, '14-nist-sp-800-53', 'retrieved', '9DC53BA3E9753340C59340290EAE9435AAAC9969360E8564CE3C5EC7A58F5954', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
