VALUES ('doc-14-nist-sp-800-53-p345-1', 'doc-14-nist-sp-800-53', '', 345, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 318 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p345-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '6578BA3EB7E8653F47F2FD9FCE6C0973C64B77045A6905778A3FB904E78225E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
