INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p345-2', 'doc-14-nist-sp-800-53', '', 345, 'adversaries use to compromise one system component will be effective against other system components, thus further increasing the adversary work factor to successfully complete planned attacks. An increase in diversity may add complexity and management overhead that could ultimately lead to mistakes and unauthorized configurations.', 'kb-doc-14-nist-sp-800-53-p345-2', 0, 45, '14-nist-sp-800-53', 'retrieved', 'F3E04EB3D12BB2B2B91A61B3DF35DB630AB41BBE74F629F58524940F0DDA7701', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
