VALUES ('doc-14-nist-sp-800-53-p346-1', 'doc-14-nist-sp-800-53', '', 346, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 319 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p346-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C2B90236293928B29073A16E262D5A4EA222811BB056562E402B6CA51A90729E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
