VALUES ('doc-14-nist-sp-800-53-p348-1', 'doc-14-nist-sp-800-53', '', 348, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 321 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p348-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '874B3BC67CFABA30D4366660DE7CBDFA37E48F10DD4C05C40FB893E925F3668F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
