INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p348-12', 'doc-14-nist-sp-800-53', '', 348, '(2) NON-MODIFIABLE EXECUTABLE PROGRAMS | INTEGRITY PROTECTION ON READ-ONLY MEDIA Protect the integrity of information prior to storage on read-only media and control the media after such information has been recorded onto the media.', 'kb-doc-14-nist-sp-800-53-p348-12', 0, 34, '14-nist-sp-800-53', 'retrieved', 'B3A78EC5AE935C9196DF121BA5980ABF352E7BB96602F47AE43552DAC90D4594', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p348-13', 'doc-14-nist-sp-800-53', '', 348, 'Discussion: Controls prevent the substitution of media into systems or the reprogramming of programmable read-only media prior to installation into the systems. Integrity protection controls include a combination of prevention, detection, and response.', 'kb-doc-14-nist-sp-800-53-p348-13', 0, 33, '14-nist-sp-800-53', 'retrieved', '8DD867720B58C669A849C5987AB527A4220D5F028AC39478B1A9B030632EC97F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
