VALUES ('doc-14-nist-sp-800-53-p350-1', 'doc-14-nist-sp-800-53', '', 350, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 323 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p350-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '1D00386A8E3F70A437DA10470E5B8A53BDFEAE986E0344FC2BCE270C0B238F8F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
