INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p350-2', 'doc-14-nist-sp-800-53', '', 350, 'Discussion: SC-36 and CP-9(6) require the duplication of systems or system components in distributed locations. The synchronization of duplicated and redundant services and data helps to ensure that information contained in the distributed locations can be used in the mission or business functions of organizations, as needed.', 'kb-doc-14-nist-sp-800-53-p350-2', 0, 47, '14-nist-sp-800-53', 'retrieved', '7FFED9CE94D0D9A65767D0B7C607EDFCFFC310F7B190CBF6158D87437E0ADF11', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
