VALUES ('doc-14-nist-sp-800-53-p350-7', 'doc-14-nist-sp-800-53', '', 350, 'Related Controls: AC-2, CM-3, CM-5, CM-7, IA-2, IA-4, IA-5, MA-4, SC-12, SI-3, SI-4, SI-7.', 'kb-doc-14-nist-sp-800-53-p350-7', 0, 14, '14-nist-sp-800-53', 'retrieved', 'E1D5960918CF7C9D4457FB90580D0E2018430E17F2142C24A343077949DD3461', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
