INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p350-8', 'doc-14-nist-sp-800-53', '', 350, 'Control Enhancements: (1) OUT-OF-BAND CHANNELS | ENSURE DELIVERY AND TRANSMISSION Employ [Assignment: organization-defined controls] to ensure that only [Assignment: organization-defined individuals or systems] receive the following information, system components, or devices: [Assignment: organization-defined information, system components, or devices].', 'kb-doc-14-nist-sp-800-53-p350-8', 0, 38, '14-nist-sp-800-53', 'retrieved', 'EBB3EFB47A04888CFFF406FE1570C72A4194E1B87A0377D30E745DE923CFC6DA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
