INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p350-9', 'doc-14-nist-sp-800-53', '', 350, 'Discussion: Techniques employed by organizations to ensure that only designated systems or individuals receive certain information, system components, or devices include sending authenticators via an approved courier service but requiring recipients to show some form of government-issued photographic identification as a condition of receipt.', 'kb-doc-14-nist-sp-800-53-p350-9', 0, 44, '14-nist-sp-800-53', 'retrieved', 'C7D2C2280C16F033B327C62329EBA86BE47A98D990CCD54F475FF4A730414C6C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
