INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p350-12', 'doc-14-nist-sp-800-53', '', 350, 'SC-38 OPERATIONS SECURITY Control: Employ the following operations security controls to protect key organizational information throughout the system development life cycle: [Assignment: organization-defined operations security controls].', 'kb-doc-14-nist-sp-800-53-p350-12', 0, 26, '14-nist-sp-800-53', 'retrieved', '32A63F4C9DC253835CDA4A680C494B05D7679E33EB7D542EF4231B05093D3551', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
