VALUES ('doc-14-nist-sp-800-53-p351-1', 'doc-14-nist-sp-800-53', '', 351, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 324 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p351-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D3DB63CC8B738D872A2271DA1374450D0DD0586DF371BA1F881D4636B37012CB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
