INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p351-2', 'doc-14-nist-sp-800-53', '', 351, 'applied to organizational systems and the environments in which those systems operate. OPSEC controls protect the confidentiality of information, including limiting the sharing of information with suppliers, potential suppliers, and other non-organizational elements and individuals.', 'kb-doc-14-nist-sp-800-53-p351-2', 0, 35, '14-nist-sp-800-53', 'retrieved', '18A5C8464B15DA94DE09078C36C92D8102EAB2ABBFB21F7C6BE5A186B4059555', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
