INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p351-3', 'doc-14-nist-sp-800-53', '', 351, 'Information critical to organizational mission and business functions includes user identities, element uses, suppliers, supply chain processes, functional requirements, security requirements, system design specifications, testing and evaluation protocols, and security control implementation details.', 'kb-doc-14-nist-sp-800-53-p351-3', 0, 33, '14-nist-sp-800-53', 'retrieved', '04B588F93A03E720AEADC03FEB6E7A21D74470552C859652A6B76295DA1F3754', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
