INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p351-19', 'doc-14-nist-sp-800-53', '', 351, 'Discussion: Wireless link protection applies to internal and external wireless communication links that may be visible to individuals who are not authorized system users. Adversaries can', 'kb-doc-14-nist-sp-800-53-p351-19', 0, 26, '14-nist-sp-800-53', 'retrieved', 'ACDBF40C1C26E9E5BAC46F69A12743D81B3AA7AF7FBC4E1EC2DC1C0FC24D8D19', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
