INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p353-2', 'doc-14-nist-sp-800-53', '', 353, 'for the purposes of intelligence exploitation by ensuring that anti-fingerprinting alterations to signal parameters are not predictable by unauthorized individuals. It also provides anonymity when required. Radio fingerprinting techniques identify the unique signal parameters of transmitters to fingerprint such transmitters for purposes of tracking and mission or user identification.', 'kb-doc-14-nist-sp-800-53-p353-2', 0, 49, '14-nist-sp-800-53', 'retrieved', '643700D578DCB7900FD536145EBA1A6B22B8B533597186F1CFD7753509CC3C47', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
