INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-3', 'doc-14-nist-sp-800-53', '', 356, 'Discussion: Synchronization of internal system clocks with an authoritative source provides uniformity of time stamps for systems with multiple system clocks and systems connected over a network.', 'kb-doc-14-nist-sp-800-53-p356-3', 0, 27, '14-nist-sp-800-53', 'retrieved', 'F61528D6906B389A8FDD1E45F3BA5A848F4559501DCE6946F06E68F16B0E830F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
