INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-5', 'doc-14-nist-sp-800-53', '', 356, '(2) SYSTEM TIME SYNCHRONIZATION | SECONDARY AUTHORITATIVE TIME SOURCE (a) Identify a secondary authoritative time source that is in a different geographic region than the primary authoritative time source; and (b) Synchronize the internal system clocks to the secondary authoritative time source if the primary authoritative time source is unavailable.', 'kb-doc-14-nist-sp-800-53-p356-5', 0, 50, '14-nist-sp-800-53', 'retrieved', '3C4F45F75C40153CA1DB3BF8ED9CE8BC8DD00B914866150B31CFA39B8827150C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-6', 'doc-14-nist-sp-800-53', '', 356, 'Discussion: It may be necessary to employ geolocation information to determine that the secondary authoritative time source is in a different geographic region.', 'kb-doc-14-nist-sp-800-53-p356-6', 0, 23, '14-nist-sp-800-53', 'retrieved', 'A727B40187C0781950016EAEEF63784A42090C4508405D301CFDC11688678659', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
