INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-9', 'doc-14-nist-sp-800-53', '', 356, 'SC-46 CROSS DOMAIN POLICY ENFORCEMENT Control: Implement a policy enforcement mechanism [Selection: physically; logically] between the physical and/or network interfaces for the connecting security domains.', 'kb-doc-14-nist-sp-800-53-p356-9', 0, 25, '14-nist-sp-800-53', 'retrieved', '3A815498A328B39B5AA45D7C89E2F0522BB25C80943AB33BE61B93ED0B304148', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-10', 'doc-14-nist-sp-800-53', '', 356, 'Discussion: For logical policy enforcement mechanisms, organizations avoid creating a logical path between interfaces to prevent the ability to bypass the policy enforcement mechanism. For physical policy enforcement mechanisms, the robustness of physical isolation afforded by the physical implementation of policy enforcement to preclude the presence of logical covert channels penetrating the security domain may be needed. Contact ncdsmo@nsa.gov for more information.', 'kb-doc-14-nist-sp-800-53-p356-10', 0, 62, '14-nist-sp-800-53', 'retrieved', '92860E7D7595972557BA76C77AC38D976118049C7393E62DF2301977903D8F39', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-14', 'doc-14-nist-sp-800-53', '', 356, 'SC-47 ALTERNATE COMMUNICATIONS PATHS Control: Establish [Assignment: organization-defined alternate communications paths] for system operations organizational command and control.', 'kb-doc-14-nist-sp-800-53-p356-14', 0, 18, '14-nist-sp-800-53', 'retrieved', '5E9BBADE83B4A0405CD80A2A875A565701641083B319C76C8BC1073E2C7FD8B5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-15', 'doc-14-nist-sp-800-53', '', 356, 'Discussion: An incident, whether adversarial- or nonadversarial-based, can disrupt established communications paths used for system operations and organizational command and control.', 'kb-doc-14-nist-sp-800-53-p356-15', 0, 21, '14-nist-sp-800-53', 'retrieved', 'B64A003CEB8E9E45D5E76E9C73773EC4C4EE9DA9EF59B989223E096EBBDE1CA6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p356-16', 'doc-14-nist-sp-800-53', '', 356, 'Alternate communications paths reduce the risk of all communications paths being affected by the same incident. To compound the problem, the inability of organizational officials to obtain timely information about disruptions or to provide timely direction to operational elements after a communications path incident, can impact the ability of the organization to respond to such incidents in a timely manner. Establishing alternate communications paths for command and control purposes, including designating alternative decision makers if primary decision makers are unavailable and establishing the extent and limitations of their actions, can greatly facilitate the organization’s ability to continue to operate and take appropriate actions during an incident.', 'kb-doc-14-nist-sp-800-53-p356-16', 0, 106, '14-nist-sp-800-53', 'retrieved', '8B6C06DBC02B401E424C7E7EFDD41F81CFAD5E67DDC602F2EAD6B6E06058C3F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
