INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p357-10', 'doc-14-nist-sp-800-53', '', 357, 'Discussion: System owners may require additional strength of mechanism and robustness to ensure domain separation and policy enforcement for specific types of threats and environments of operation. Hardware-enforced separation and policy enforcement provide greater strength of mechanism than software-enforced separation and policy enforcement.', 'kb-doc-14-nist-sp-800-53-p357-10', 0, 43, '14-nist-sp-800-53', 'retrieved', '173A3B6CF03AA1CCB19E0E8A5EBABAA1AE89643049094DF8F64DE38B0CBFE972', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
