VALUES ('doc-14-nist-sp-800-53-p360-1', 'doc-14-nist-sp-800-53', '', 360, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 333 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p360-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '8309F030F2E1CE354C3B8097FDD69AEB821402AA54104AB6564712D2488A0A81', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
