VALUES ('doc-14-nist-sp-800-53-p360-6', 'doc-14-nist-sp-800-53', '', 360, 'Related Controls: CA-5, CM-3, CM-4, CM-5, CM-6, CM-8, MA-2, RA-5, SA-8, SA-10, SA-11, SI-3, SI- 5, SI-7, SI-11.', 'kb-doc-14-nist-sp-800-53-p360-6', 0, 18, '14-nist-sp-800-53', 'retrieved', '693AC84816B7E7EE6C6C2E15E3B5A3977C00B7BDD40A0986F553F499B58E7903', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
