INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p360-7', 'doc-14-nist-sp-800-53', '', 360, 'Control Enhancements: (1) FLAW REMEDIATION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) FLAW REMEDIATION | AUTOMATED FLAW REMEDIATION STATUS Determine if system components have applicable security-relevant software and firmware updates installed using [Assignment: organization-defined automated mechanisms] [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p360-7', 0, 40, '14-nist-sp-800-53', 'retrieved', '04668A32EB870A4431AC422A2556265871C80A0642A65781795C254C0BCD240E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
