VALUES ('doc-14-nist-sp-800-53-p360-8', 'doc-14-nist-sp-800-53', '', 360, 'Discussion: Automated mechanisms can track and determine the status of known flaws for system components.', 'kb-doc-14-nist-sp-800-53-p360-8', 0, 15, '14-nist-sp-800-53', 'retrieved', 'FA58891FFF008F4E35FE484F03E182190BDEA3992A95CF8BF417A209632FAAE7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
