INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p360-10', 'doc-14-nist-sp-800-53', '', 360, '(3) FLAW REMEDIATION | TIME TO REMEDIATE FLAWS AND BENCHMARKS FOR CORRECTIVE ACTIONS (a) Measure the time between flaw identification and flaw remediation; and (b) Establish the following benchmarks for taking corrective actions: [Assignment: organization-defined benchmarks].', 'kb-doc-14-nist-sp-800-53-p360-10', 0, 36, '14-nist-sp-800-53', 'retrieved', '998A549EA4ACAA0E9A0C71B1FD7D04457CB11BE89DC24CDE6679A0C347A56A3E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
