INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p360-11', 'doc-14-nist-sp-800-53', '', 360, 'Discussion: Organizations determine the time it takes on average to correct system flaws after such flaws have been identified and subsequently establish organizational benchmarks', 'kb-doc-14-nist-sp-800-53-p360-11', 0, 24, '14-nist-sp-800-53', 'retrieved', '9B14C746D941C7979316B5BC58988EA3EFCDB8ECAB17EC8C4F27BD166A7EA95B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
