INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p361-4', 'doc-14-nist-sp-800-53', '', 361, '(4) FLAW REMEDIATION | AUTOMATED PATCH MANAGEMENT TOOLS Employ automated patch management tools to facilitate flaw remediation to the following system components: [Assignment: organization-defined system components].', 'kb-doc-14-nist-sp-800-53-p361-4', 0, 26, '14-nist-sp-800-53', 'retrieved', '7AC3211A7899CD6C473E2F52A4F553845CABF90423AD210AD4AEEC4DB38B1481', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
