INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p361-5', 'doc-14-nist-sp-800-53', '', 361, 'Discussion: Using automated tools to support patch management helps to ensure the timeliness and completeness of system patching operations.', 'kb-doc-14-nist-sp-800-53-p361-5', 0, 19, '14-nist-sp-800-53', 'retrieved', 'E64826E6E219257DF899F4DBF5E796F7334E879C64D89425176C1CAC5FCCA4D1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
