VALUES ('doc-14-nist-sp-800-53-p361-13', 'doc-14-nist-sp-800-53', '', 361, 'References: [OMB A-130], [FIPS 140-3], [FIPS 186-4], [SP 800-39], [SP 800-40], [SP 800-128], [IR 7788].', 'kb-doc-14-nist-sp-800-53-p361-13', 0, 15, '14-nist-sp-800-53', 'retrieved', 'B043914DE45F80193C5240AE27E3FEF03C61D61B9EF49E5B6A9CA026CA736A9A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
