INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p362-2', 'doc-14-nist-sp-800-53', '', 362, 'd. Address the receipt of false positives during malicious code detection and eradication and the resulting potential impact on the availability of the system.', 'kb-doc-14-nist-sp-800-53-p362-2', 0, 24, '14-nist-sp-800-53', 'retrieved', '1B3FC8D6397A86AA746E6D44896901C639552D00B2297EE22BA0401255236892', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
