INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p362-8', 'doc-14-nist-sp-800-53', '', 362, 'Control Enhancements: (1) MALICIOUS CODE PROTECTION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) MALICIOUS CODE PROTECTION | AUTOMATIC UPDATES [Withdrawn: Incorporated into SI-3.] (3) MALICIOUS CODE PROTECTION | NON-PRIVILEGED USERS [Withdrawn: Incorporated into AC-6(10).] (4) MALICIOUS CODE PROTECTION | UPDATES ONLY BY PRIVILEGED USERS Update malicious code protection mechanisms only when directed by a privileged user.', 'kb-doc-14-nist-sp-800-53-p362-8', 0, 57, '14-nist-sp-800-53', 'retrieved', '19B7DDE2EFB55DE6DAEE3298EF93D4EF8115CCEBCA6143538D7FCE8F15A91D50', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
