INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p362-9', 'doc-14-nist-sp-800-53', '', 362, 'Discussion: Protection mechanisms for malicious code are typically categorized as security- related software and, as such, are only updated by organizational personnel with appropriate access privileges.', 'kb-doc-14-nist-sp-800-53-p362-9', 0, 26, '14-nist-sp-800-53', 'retrieved', '904EB85DA333E3F5F889245860BC124DD377773F633542A3A5713D2D02199367', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
