VALUES ('doc-14-nist-sp-800-53-p363-1', 'doc-14-nist-sp-800-53', '', 363, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 336 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p363-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '50D5289925829D9CC3AA5DAE49D6AD1F664A3AC0CF61BA546C72DC80444078EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
