INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p363-2', 'doc-14-nist-sp-800-53', '', 363, '[Withdrawn: Incorporated into MP-7.] (6) MALICIOUS CODE PROTECTION | TESTING AND VERIFICATION (a) Test malicious code protection mechanisms [Assignment: organization-defined frequency] by introducing known benign code into the system; and (b) Verify that the detection of the code and the associated incident reporting occur.', 'kb-doc-14-nist-sp-800-53-p363-2', 0, 44, '14-nist-sp-800-53', 'retrieved', '53A612F10939B76765CB88BE8BB92793C8673C8DE254077C80CD5675575C9A2B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
