VALUES ('doc-14-nist-sp-800-53-p365-1', 'doc-14-nist-sp-800-53', '', 365, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 338 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p365-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D64579A70B0D025C9C8B25132481CA15BB6E0F907EAA052FDA5FE5021DD5EA24', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
