VALUES ('doc-14-nist-sp-800-53-p365-2', 'doc-14-nist-sp-800-53', '', 365, 'Related Controls: AC-2, AC-3, AC-4, AC-8, AC-17, AU-2, AU-6, AU-7, AU-9, AU-12, AU-13, AU-14, CA-7, CM-3, CM-6, CM-8, CM-11, IA-10, IR-4, MA-3, MA-4, PL-9, PM-12, RA-5, RA-10, SC-5, SC-7, SC-18, SC-26, SC-31, SC-35, SC-36, SC-37, SC-43, SI-3, SI-6, SI-7, SR-9, SR-10.', 'kb-doc-14-nist-sp-800-53-p365-2', 0, 41, '14-nist-sp-800-53', 'retrieved', 'CA40FDF4009D5A96981DAD7279E5E731B9C45B4D605C2F568A787777705E3C55', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
