INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-3', 'doc-14-nist-sp-800-53', '', 365, 'Control Enhancements: (1) SYSTEM MONITORING | SYSTEM-WIDE INTRUSION DETECTION SYSTEM Connect and configure individual intrusion detection tools into a system-wide intrusion detection system.', 'kb-doc-14-nist-sp-800-53-p365-3', 0, 23, '14-nist-sp-800-53', 'retrieved', '2807383B01391C3FB35B417123F28FA789398A5B0FC145B4948727BAAF65061B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-4', 'doc-14-nist-sp-800-53', '', 365, 'Discussion: Linking individual intrusion detection tools into a system-wide intrusion detection system provides additional coverage and effective detection capabilities. The information contained in one intrusion detection tool can be shared widely across the organization, making the system-wide detection capability more robust and powerful.', 'kb-doc-14-nist-sp-800-53-p365-4', 0, 43, '14-nist-sp-800-53', 'retrieved', '1ED5C5E14F0622C6AFBC2301725C6E2AC2A28FCCA485423E9E009E246BC3AAFF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-6', 'doc-14-nist-sp-800-53', '', 365, '(2) SYSTEM MONITORING | AUTOMATED TOOLS AND MECHANISMS FOR REAL-TIME ANALYSIS Employ automated tools and mechanisms to support near real-time analysis of events.', 'kb-doc-14-nist-sp-800-53-p365-6', 0, 23, '14-nist-sp-800-53', 'retrieved', 'D207A43EDFBC8725254A2A186C6EBCB7EB547742B466E1252A4A36C155174A3A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-7', 'doc-14-nist-sp-800-53', '', 365, 'Discussion: Automated tools and mechanisms include host-based, network-based, transport-based, or storage-based event monitoring tools and mechanisms or security information and event management (SIEM) technologies that provide real-time analysis of alerts and notifications generated by organizational systems. Automated monitoring techniques can create unintended privacy risks because automated controls may connect to external or otherwise unrelated systems. The matching of records between these systems may create linkages with unintended consequences. Organizations assess and document these risks in their privacy impact assessment and make determinations that are in alignment with their privacy program plan.', 'kb-doc-14-nist-sp-800-53-p365-7', 0, 91, '14-nist-sp-800-53', 'retrieved', '64E8DCBBF953864F97CCAD7C0EE54BC3894FD8AADE7E44F49BB08560EBBFADA9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-9', 'doc-14-nist-sp-800-53', '', 365, '(3) SYSTEM MONITORING | AUTOMATED TOOL AND MECHANISM INTEGRATION Employ automated tools and mechanisms to integrate intrusion detection tools and mechanisms into access control and flow control mechanisms.', 'kb-doc-14-nist-sp-800-53-p365-9', 0, 28, '14-nist-sp-800-53', 'retrieved', '79115CBF194C2A252ED427D0BEE3C6500378B34BD7F697BFCC976032037618DF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-10', 'doc-14-nist-sp-800-53', '', 365, 'Discussion: Using automated tools and mechanisms to integrate intrusion detection tools and mechanisms into access and flow control mechanisms facilitates a rapid response to attacks by enabling the reconfiguration of mechanisms in support of attack isolation and elimination.', 'kb-doc-14-nist-sp-800-53-p365-10', 0, 38, '14-nist-sp-800-53', 'retrieved', '70B25713A9FF4CBB543B129DFD05D45266854A7107F24B0F04E1476132EC5AC6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-12', 'doc-14-nist-sp-800-53', '', 365, '(4) SYSTEM MONITORING | INBOUND AND OUTBOUND COMMUNICATIONS TRAFFIC (a) Determine criteria for unusual or unauthorized activities or conditions for inbound and outbound communications traffic; (b) Monitor inbound and outbound communications traffic [Assignment: organization- defined frequency] for [Assignment: organization-defined unusual or unauthorized activities or conditions].', 'kb-doc-14-nist-sp-800-53-p365-12', 0, 45, '14-nist-sp-800-53', 'retrieved', '0741317C44B983667D96D4022367EC19C5C7590BB6F0B42134E4DDD3445A1258', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p365-13', 'doc-14-nist-sp-800-53', '', 365, 'Discussion: Unusual or unauthorized activities or conditions related to system inbound and outbound communications traffic includes internal traffic that indicates the presence of malicious code or unauthorized use of legitimate code or credentials within organizational systems or propagating among system components, signaling to external systems, and the unauthorized exporting of information. Evidence of malicious code or unauthorized use of legitimate code or credentials is used to identify potentially compromised systems or system components.', 'kb-doc-14-nist-sp-800-53-p365-13', 0, 73, '14-nist-sp-800-53', 'retrieved', 'A5E3A4FF817DE47E542FED80D1277BF4E11CC65398C114F9BF03261C782F166D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p366-1', 'doc-14-nist-sp-800-53', '', 366, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 339 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p366-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '92A588927F3BFFD7C34C003744ABDDA057C505D3BFAF68A3BFDAE71936EDCE5C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
