INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p366-11', 'doc-14-nist-sp-800-53', '', 366, '(10) SYSTEM MONITORING | VISIBILITY OF ENCRYPTED COMMUNICATIONS Make provisions so that [Assignment: organization-defined encrypted communications traffic] is visible to [Assignment: organization-defined system monitoring tools and mechanisms].', 'kb-doc-14-nist-sp-800-53-p366-11', 0, 27, '14-nist-sp-800-53', 'retrieved', '5FEC825AABF78BCAE3054A3BBE34BF1D465F1BC36F9EB4056689C651C07CD1FB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p366-12', 'doc-14-nist-sp-800-53', '', 366, 'Discussion: Organizations balance the need to encrypt communications traffic to protect data confidentiality with the need to maintain visibility into such traffic from a monitoring perspective. Organizations determine whether the visibility requirement applies to internal encrypted traffic, encrypted traffic intended for external destinations, or a subset of the traffic types.', 'kb-doc-14-nist-sp-800-53-p366-12', 0, 50, '14-nist-sp-800-53', 'retrieved', '97FCF40AB185D6B4D434792DFDDBFC31DB67C08F66C64B4FD3A17CC05A4516FD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
