VALUES ('doc-14-nist-sp-800-53-p367-1', 'doc-14-nist-sp-800-53', '', 367, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 340 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p367-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '40E4DFD9D754DAFABA005E6F97DF1E48C32E033BE5C37EAC3E8B4E79F1701E17', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
