INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-2', 'doc-14-nist-sp-800-53', '', 367, 'Analyze outbound communications traffic at the external interfaces to the system and selected [Assignment: organization-defined interior points within the system] to discover anomalies.', 'kb-doc-14-nist-sp-800-53-p367-2', 0, 23, '14-nist-sp-800-53', 'retrieved', '8700E5C32B1288F588419B97CDD83E46DCB101667672929E27FEC0E8FA2D0A4A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
