INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-3', 'doc-14-nist-sp-800-53', '', 367, 'Discussion: Organization-defined interior points include subnetworks and subsystems.', 'kb-doc-14-nist-sp-800-53-p367-3', 0, 8, '14-nist-sp-800-53', 'retrieved', '35762A55F52E44CF715279120B7A1F21BD23926462FCE3E12D5EEF7EDED27138', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-4', 'doc-14-nist-sp-800-53', '', 367, 'Anomalies within organizational systems include large file transfers, long-time persistent connections, attempts to access information from unexpected locations, the use of unusual protocols and ports, the use of unmonitored network protocols (e.g., IPv6 usage during IPv4 transition), and attempted communications with suspected malicious external addresses.', 'kb-doc-14-nist-sp-800-53-p367-4', 0, 45, '14-nist-sp-800-53', 'retrieved', 'D18943177344F70095416526785E6AEB282FC52A840DFBF77F5A8A4F952416A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-6', 'doc-14-nist-sp-800-53', '', 367, '(12) SYSTEM MONITORING | AUTOMATED ORGANIZATION-GENERATED ALERTS Alert [Assignment: organization-defined personnel or roles] using [Assignment: organization-defined automated mechanisms] when the following indications of inappropriate or unusual activities with security or privacy implications occur: [Assignment: organization-defined activities that trigger alerts].', 'kb-doc-14-nist-sp-800-53-p367-6', 0, 39, '14-nist-sp-800-53', 'retrieved', '5C568622422E14C63929E451BF06B76D48C84DB40D3DC2326B18700F4A62BEC5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
