INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-7', 'doc-14-nist-sp-800-53', '', 367, 'Discussion: Organizational personnel on the system alert notification list include system administrators, mission or business owners, system owners, senior agency information security officer, senior agency official for privacy, system security officers, or privacy officers.', 'kb-doc-14-nist-sp-800-53-p367-7', 0, 34, '14-nist-sp-800-53', 'retrieved', '085F3EFB605A19B853899557C1A7852FAA8AA5F096AE1CD592D7CBDD201DA00F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-8', 'doc-14-nist-sp-800-53', '', 367, 'Automated organization-generated alerts are the security alerts generated by organizations and transmitted using automated means. The sources for organization-generated alerts are focused on other entities such as suspicious activity reports and reports on potential insider threats. In contrast to alerts generated by the organization, alerts generated by the system in SI-4(5) focus on information sources that are internal to the systems, such as audit records.', 'kb-doc-14-nist-sp-800-53-p367-8', 0, 65, '14-nist-sp-800-53', 'retrieved', '6397489154025303D5662CFEE790D9604574BFB00DDEC9539EA501FB9F59E146', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-10', 'doc-14-nist-sp-800-53', '', 367, '(13) SYSTEM MONITORING | ANALYZE TRAFFIC AND EVENT PATTERNS (a) Analyze communications traffic and event patterns for the system; (b) Develop profiles representing common traffic and event patterns; and (c) Use the traffic and event profiles in tuning system-monitoring devices.', 'kb-doc-14-nist-sp-800-53-p367-10', 0, 40, '14-nist-sp-800-53', 'retrieved', '4D31EB2825CF2F0E904B976BAA7992EC224D40EE13A12FED00B78C8ED92F5D56', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-11', 'doc-14-nist-sp-800-53', '', 367, 'Discussion: Identifying and understanding common communications traffic and event patterns help organizations provide useful information to system monitoring devices to more effectively identify suspicious or anomalous traffic and events when they occur. Such information can help reduce the number of false positives and false negatives during system monitoring.', 'kb-doc-14-nist-sp-800-53-p367-11', 0, 48, '14-nist-sp-800-53', 'retrieved', 'F0920F860497B892135589E493D10F67C81E3D03B3013AE8401E460109804463', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-13', 'doc-14-nist-sp-800-53', '', 367, '(14) SYSTEM MONITORING | WIRELESS INTRUSION DETECTION Employ a wireless intrusion detection system to identify rogue wireless devices and to detect attack attempts and potential compromises or breaches to the system.', 'kb-doc-14-nist-sp-800-53-p367-13', 0, 31, '14-nist-sp-800-53', 'retrieved', '854BB7F1763032C1453957C484C76E6E9F72C66F61BB7824F8AB361E93412B4A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-14', 'doc-14-nist-sp-800-53', '', 367, 'Discussion: Wireless signals may radiate beyond organizational facilities. Organizations proactively search for unauthorized wireless connections, including the conduct of thorough scans for unauthorized wireless access points. Wireless scans are not limited to those areas within facilities containing systems but also include areas outside of facilities to verify that unauthorized wireless access points are not connected to organizational systems.', 'kb-doc-14-nist-sp-800-53-p367-14', 0, 58, '14-nist-sp-800-53', 'retrieved', 'B853FF2712E439204EC368333CC361A8769156306074D0411645F0347B371831', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p367-16', 'doc-14-nist-sp-800-53', '', 367, '(15) SYSTEM MONITORING | WIRELESS TO WIRELINE COMMUNICATIONS Employ an intrusion detection system to monitor wireless communications traffic as the traffic passes from wireless to wireline networks.', 'kb-doc-14-nist-sp-800-53-p367-16', 0, 27, '14-nist-sp-800-53', 'retrieved', '22583A5A58D5BBD74B00878D6275D7180A93A7C0F31FC5E34189E51D35216BB3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
