VALUES ('doc-14-nist-sp-800-53-p369-1', 'doc-14-nist-sp-800-53', '', 369, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 342 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p369-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'FAAF09655A807B0E2409E0798994E130A9D1034A464C09CD5F2C3C2E310BC9EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
