INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-2', 'doc-14-nist-sp-800-53', '', 369, 'Implement [Assignment: organization-defined additional monitoring] of individuals who have been identified by [Assignment: organization-defined sources] as posing an increased level of risk.', 'kb-doc-14-nist-sp-800-53-p369-2', 0, 22, '14-nist-sp-800-53', 'retrieved', 'EB73DF877CFC84BFC06AAA562860E96FA9308C6101A88CBCDFD2A22094394C1B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-3', 'doc-14-nist-sp-800-53', '', 369, 'Discussion: Indications of increased risk from individuals can be obtained from different sources, including personnel records, intelligence agencies, law enforcement organizations, and other sources. The monitoring of individuals is coordinated with the management, legal, security, privacy, and human resource officials who conduct such monitoring. Monitoring is conducted in accordance with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p369-3', 0, 60, '14-nist-sp-800-53', 'retrieved', '2174575BA58E06CE745DA1C704BF40CDE4B6A717194B10315307D9C7A8414C1E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-5', 'doc-14-nist-sp-800-53', '', 369, '(20) SYSTEM MONITORING | PRIVILEGED USERS Implement the following additional monitoring of privileged users: [Assignment: organization-defined additional monitoring].', 'kb-doc-14-nist-sp-800-53-p369-5', 0, 18, '14-nist-sp-800-53', 'retrieved', '7F424EBC4C6B185B8E91FBD0F18E851F1B429DD508F097D7CC5B389DE8B57E1D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-6', 'doc-14-nist-sp-800-53', '', 369, 'Discussion: Privileged users have access to more sensitive information, including security- related information, than the general user population. Access to such information means that privileged users can potentially do greater damage to systems and organizations than non-privileged users. Therefore, implementing additional monitoring on privileged users helps to ensure that organizations can identify malicious activity at the earliest possible time and take appropriate actions.', 'kb-doc-14-nist-sp-800-53-p369-6', 0, 63, '14-nist-sp-800-53', 'retrieved', '45A84C01E5C45E8C7997FCBAEFC952F1EA05D4A6D1DE5DD9DF324CB49029CA16', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-8', 'doc-14-nist-sp-800-53', '', 369, '(21) SYSTEM MONITORING | PROBATIONARY PERIODS Implement the following additional monitoring of individuals during [Assignment: organization-defined probationary period]: [Assignment: organization-defined additional monitoring].', 'kb-doc-14-nist-sp-800-53-p369-8', 0, 22, '14-nist-sp-800-53', 'retrieved', '208EAF79FE355A4283A4355362DE1A4392B634B605137C3E1E72DC639EB153D5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-9', 'doc-14-nist-sp-800-53', '', 369, 'Discussion: During probationary periods, employees do not have permanent employment status within organizations. Without such status or access to information that is resident on the system, additional monitoring can help identify any potentially malicious activity or inappropriate behavior.', 'kb-doc-14-nist-sp-800-53-p369-9', 0, 38, '14-nist-sp-800-53', 'retrieved', '95CDE329CBCC1B0EFF9CE993AFA15A4296D32A0E783B949324CE1F8C88589849', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
