INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-11', 'doc-14-nist-sp-800-53', '', 369, '(22) SYSTEM MONITORING | UNAUTHORIZED NETWORK SERVICES (a) Detect network services that have not been authorized or approved by [Assignment: organization-defined authorization or approval processes]; and (b) [Selection (one or more): Audit; Alert [Assignment: organization-defined personnel or roles]] when detected.', 'kb-doc-14-nist-sp-800-53-p369-11', 0, 40, '14-nist-sp-800-53', 'retrieved', 'CC009A959A4477E22D348AD44E30967C8EDD31B381319A2FECDE464BE1206C0A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
