INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-12', 'doc-14-nist-sp-800-53', '', 369, 'Discussion: Unauthorized or unapproved network services include services in service- oriented architectures that lack organizational verification or validation and may therefore be unreliable or serve as malicious rogues for valid services.', 'kb-doc-14-nist-sp-800-53-p369-12', 0, 31, '14-nist-sp-800-53', 'retrieved', '7B37AD77E8AC11329FFC86196FE2BF952D2CE952F7F9486CDB75936C8E8B6A3F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
