INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-14', 'doc-14-nist-sp-800-53', '', 369, '(23) SYSTEM MONITORING | HOST-BASED DEVICES Implement the following host-based monitoring mechanisms at [Assignment: organization-defined system components]: [Assignment: organization-defined host-based monitoring mechanisms].', 'kb-doc-14-nist-sp-800-53-p369-14', 0, 22, '14-nist-sp-800-53', 'retrieved', '133D6FCCB20247DEDECD35D639B6592B8E74BDCDF9E289875211657D714532A4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
