INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p369-15', 'doc-14-nist-sp-800-53', '', 369, 'Discussion: Host-based monitoring collects information about the host (or system in which it resides). System components in which host-based monitoring can be implemented include servers, notebook computers, and mobile devices. Organizations may consider employing host-based monitoring mechanisms from multiple product developers or vendors.', 'kb-doc-14-nist-sp-800-53-p369-15', 0, 43, '14-nist-sp-800-53', 'retrieved', 'CFB2AA7278B49305264194FC492C1BFFB1CB98821139256741B93C099D19B869', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
