VALUES ('doc-14-nist-sp-800-53-p370-1', 'doc-14-nist-sp-800-53', '', 370, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 343 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p370-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '86349824864451C6E7278FAA252AE7C3E21FC3BA3309E986C9101ECFFB79DD61', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
