INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p370-2', 'doc-14-nist-sp-800-53', '', 370, '(24) SYSTEM MONITORING | INDICATORS OF COMPROMISE Discover, collect, and distribute to [Assignment: organization-defined personnel or roles], indicators of compromise provided by [Assignment: organization-defined sources].', 'kb-doc-14-nist-sp-800-53-p370-2', 0, 25, '14-nist-sp-800-53', 'retrieved', '4A62D3BC5F51B20DF3B0A67D32A5E456773E9360FBF3E7D0E7BC5E194B6F164A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p370-3', 'doc-14-nist-sp-800-53', '', 370, 'Discussion: Indicators of compromise (IOC) are forensic artifacts from intrusions that are identified on organizational systems at the host or network level. IOCs provide valuable information on systems that have been compromised. IOCs can include the creation of registry key values. IOCs for network traffic include Universal Resource Locator or protocol elements that indicate malicious code command and control servers. The rapid distribution and adoption of IOCs can improve information security by reducing the time that systems and organizations are vulnerable to the same exploit or attack. Threat indicators, signatures, tactics, techniques, procedures, and other indicators of compromise may be available via government and non-government cooperatives, including the Forum of Incident Response and Security Teams, the United States Computer Emergency Readiness Team, the Defense Industrial Base Cybersecurity Information Sharing Program, and the CERT Coordination Center.', 'kb-doc-14-nist-sp-800-53-p370-3', 0, 135, '14-nist-sp-800-53', 'retrieved', 'D26C22EB2D9162C0285FC35B85D8C481104312A0D61B0D5DDB5696710925B29C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p370-5', 'doc-14-nist-sp-800-53', '', 370, '(25) SYSTEM MONITORING | OPTIMIZE NETWORK TRAFFIC ANALYSIS Provide visibility into network traffic at external and key internal system interfaces to optimize the effectiveness of monitoring devices.', 'kb-doc-14-nist-sp-800-53-p370-5', 0, 27, '14-nist-sp-800-53', 'retrieved', '8F17414AD7B2A633CAE9E4128DC7CDB2A67DD8241D1FC73BE5F192F070A1CFF9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
