VALUES ('doc-14-nist-sp-800-53-p370-8', 'doc-14-nist-sp-800-53', '', 370, 'References: [OMB A-130], [FIPS 140-3], [SP 800-61], [SP 800-83], [SP 800-92], [SP 800-94], [SP 800-137].', 'kb-doc-14-nist-sp-800-53-p370-8', 0, 15, '14-nist-sp-800-53', 'retrieved', '23E8662F96375CB11CBCC57E4EB3304E829CF9B83E128B9EE855B57835173E74', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
