INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p370-9', 'doc-14-nist-sp-800-53', '', 370, 'SI-5 SECURITY ALERTS, ADVISORIES, AND DIRECTIVES Control: a. Receive system security alerts, advisories, and directives from [Assignment: organization- defined external organizations] on an ongoing basis; b. Generate internal security alerts, advisories, and directives as deemed necessary; c. Disseminate security alerts, advisories, and directives to: [Selection (one or more): [Assignment: organization-defined personnel or roles]; [Assignment: organization-defined elements within the organization]; [Assignment: organization-defined external organizations]]; and d. Implement security directives in accordance with established time frames, or notify the issuing organization of the degree of noncompliance.', 'kb-doc-14-nist-sp-800-53-p370-9', 0, 84, '14-nist-sp-800-53', 'retrieved', 'BAB6EDDB5C4851A300914360DEFF6DEF6B7F2A65B80FBA245E5F2C45C70D7995', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
