INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p371-4', 'doc-14-nist-sp-800-53', '', 371, 'Control Enhancements: (1) SECURITY ALERTS, ADVISORIES, AND DIRECTIVES | AUTOMATED ALERTS AND ADVISORIES Broadcast security alert and advisory information throughout the organization using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p371-4', 0, 27, '14-nist-sp-800-53', 'retrieved', '7418CD4F4E8A07E731562D35FAE082CAAFD9114A7E93A8E197BDA3C87CDEEEA0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
