INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p371-9', 'doc-14-nist-sp-800-53', '', 371, 'Discussion: Transitional states for systems include system startup, restart, shutdown, and abort.', 'kb-doc-14-nist-sp-800-53-p371-9', 0, 12, '14-nist-sp-800-53', 'retrieved', 'E2204857DD6D05E67C6553502B8029ACE4071E653BC9ED181FB7EE10E4658B25', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
