INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p371-10', 'doc-14-nist-sp-800-53', '', 371, 'System notifications include hardware indicator lights, electronic alerts to system administrators, and messages to local computer consoles. In contrast to security function verification, privacy function verification ensures that privacy functions operate as expected and are approved by the senior agency official for privacy or that privacy attributes are applied or used as expected.', 'kb-doc-14-nist-sp-800-53-p371-10', 0, 53, '14-nist-sp-800-53', 'retrieved', '76353D3F78B94EA1FC7973176451703696FB58487A640DBA1CFB07DE899F30A0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
