VALUES ('doc-14-nist-sp-800-53-p371-12', 'doc-14-nist-sp-800-53', '', 371, 'Control Enhancements: (1) SECURITY AND PRIVACY FUNCTION VERIFICATION | NOTIFICATION OF FAILED SECURITY TESTS [Withdrawn: Incorporated into SI-6.] (2) SECURITY AND PRIVACY FUNCTION VERIFICATION | AUTOMATION SUPPORT FOR DISTRIBUTED TESTING Implement automated mechanisms to support the management of distributed security and privacy function testing.', 'kb-doc-14-nist-sp-800-53-p371-12', 0, 44, '14-nist-sp-800-53', 'retrieved', '0BF093C5E44270A718A3A1B5936594CA0073C73B269316C4B0C6E7A877CE8DBB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
