INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-5', 'doc-14-nist-sp-800-53', '', 372, 'Discussion: Organizational personnel with potential interest in the results of the verification of security and privacy functions include systems security officers, senior agency information security officers, and senior agency officials for privacy.', 'kb-doc-14-nist-sp-800-53-p372-5', 0, 32, '14-nist-sp-800-53', 'retrieved', 'C2AA84A9F314272123FEA8154616D45FE3E475D07486FDAC80BDABA80CB4182A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
