INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-8', 'doc-14-nist-sp-800-53', '', 372, 'SI-7 SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY Control: a. Employ integrity verification tools to detect unauthorized changes to the following software, firmware, and information: [Assignment: organization-defined software, firmware, and information]; and b. Take the following actions when unauthorized changes to the software, firmware, and information are detected: [Assignment: organization-defined actions].', 'kb-doc-14-nist-sp-800-53-p372-8', 0, 49, '14-nist-sp-800-53', 'retrieved', 'B2BACCD772BA0F5E72955E080159677199646306031F30287DF0AD3437CFF0EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-9', 'doc-14-nist-sp-800-53', '', 372, 'Discussion: Unauthorized changes to software, firmware, and information can occur due to errors or malicious activity. Software includes operating systems (with key internal components, such as kernels or drivers), middleware, and applications. Firmware interfaces include Unified Extensible Firmware Interface (UEFI) and Basic Input/Output System (BIOS). Information includes personally identifiable information and metadata that contains security and privacy attributes associated with information. Integrity-checking mechanisms— including parity checks, cyclical redundancy checks, cryptographic hashes, and associated tools— can automatically monitor the integrity of systems and hosted applications.', 'kb-doc-14-nist-sp-800-53-p372-9', 0, 84, '14-nist-sp-800-53', 'retrieved', 'B2CF911C291A8CF1BCB3E676BEE9AD4531266E5E6593461A359B88353B4654B5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-10', 'doc-14-nist-sp-800-53', '', 372, 'Related Controls: AC-4, CM-3, CM-7, CM-8, MA-3, MA-4, RA-5, SA-8, SA-9, SA-10, SC-8, SC-12, SC-13, SC-28, SC-37, SI-3, SR-3, SR-4, SR-5, SR-6, SR-9, SR-10, SR-11.', 'kb-doc-14-nist-sp-800-53-p372-10', 0, 25, '14-nist-sp-800-53', 'retrieved', 'F2783CEAC0D02D525D35D7BAE23B870DAF80DF22169AA19F798CEC68F4C5732A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
