INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-11', 'doc-14-nist-sp-800-53', '', 372, 'Control Enhancements: (1) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | INTEGRITY CHECKS Perform an integrity check of [Assignment: organization-defined software, firmware, and information] [Selection (one or more): at startup; at [Assignment: organization-defined transitional states or security-relevant events]; [Assignment: organization-defined frequency]].', 'kb-doc-14-nist-sp-800-53-p372-11', 0, 39, '14-nist-sp-800-53', 'retrieved', 'D8668D3EC022AEB36A1D300F27B6F007A45DD36702CE9E7CDF9986FC2F8B0AD4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
