INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p372-12', 'doc-14-nist-sp-800-53', '', 372, 'Discussion: Security-relevant events include the identification of new threats to which organizational systems are susceptible and the installation of new hardware, software, or firmware. Transitional states include system startup, restart, shutdown, and abort.', 'kb-doc-14-nist-sp-800-53-p372-12', 0, 33, '14-nist-sp-800-53', 'retrieved', 'BE98F179C93833135936BE409E9DACFA4C6590AD37F743894B23113781FC658C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
