VALUES ('doc-14-nist-sp-800-53-p374-2', 'doc-14-nist-sp-800-53', '', 374, 'unauthorized changes to established configuration settings or the unauthorized elevation of system privileges.', 'kb-doc-14-nist-sp-800-53-p374-2', 0, 13, '14-nist-sp-800-53', 'retrieved', 'CC9B749181EB8D394EED5FEB90745D4F7A78095FEB5F3441FC10D40706245BC9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
