VALUES ('doc-14-nist-sp-800-53-p374-5', 'doc-14-nist-sp-800-53', '', 374, 'Discussion: Organizations select response actions based on types of software, specific software, or information for which there are potential integrity violations.', 'kb-doc-14-nist-sp-800-53-p374-5', 0, 21, '14-nist-sp-800-53', 'retrieved', 'E5DD245E1667ACD94610CDE9CC045360495DF79F7DCD50835A4633CB9C0ECCFE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
