INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p374-8', 'doc-14-nist-sp-800-53', '', 374, 'Discussion: Ensuring the integrity of boot processes is critical to starting system components in known, trustworthy states. Integrity verification mechanisms provide a level of assurance that only trusted code is executed during boot processes.', 'kb-doc-14-nist-sp-800-53-p374-8', 0, 34, '14-nist-sp-800-53', 'retrieved', 'DE5937E61CEE518EF71D78F191940CF55FAB1C1C3E0241F95F0CFBF2DFD70858', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
