INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p374-14', 'doc-14-nist-sp-800-53', '', 374, 'Discussion: Organizations verify the integrity of user-installed software prior to execution to reduce the likelihood of executing malicious code or programs that contains errors from unauthorized modifications. Organizations consider the practicality of approaches to verifying software integrity, including the availability of trustworthy checksums from software developers and vendors.', 'kb-doc-14-nist-sp-800-53-p374-14', 0, 48, '14-nist-sp-800-53', 'retrieved', '5EE0ABB9B6D5600DA57F0C52C7D3B9918EB705C3EC3AE674CECB327FE97EA610', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
