VALUES ('doc-14-nist-sp-800-53-p374-16', 'doc-14-nist-sp-800-53', '', 374, '(13) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CODE EXECUTION IN PROTECTED ENVIRONMENTS', 'kb-doc-14-nist-sp-800-53-p374-16', 0, 12, '14-nist-sp-800-53', 'retrieved', '4772F697DD6154DBA96E87670AC9AD23485EE608606C6ABFE7EFC6B47A4058D5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
