INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p375-2', 'doc-14-nist-sp-800-53', '', 375, '[Withdrawn: Moved to CM-7(7).] (14) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | BINARY OR MACHINE EXECUTABLE CODE [Withdrawn: Moved to CM-7(8).] (15) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | CODE AUTHENTICATION Implement cryptographic mechanisms to authenticate the following software or firmware components prior to installation: [Assignment: organization-defined software or firmware components].', 'kb-doc-14-nist-sp-800-53-p375-2', 0, 49, '14-nist-sp-800-53', 'retrieved', 'C8255A36FE3E392AAE066AE940C5EB10713D6BD17DAE1FFAC2A8794107E55E82', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
