INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p375-3', 'doc-14-nist-sp-800-53', '', 375, 'Discussion: Cryptographic authentication includes verifying that software or firmware components have been digitally signed using certificates recognized and approved by organizations. Code signing is an effective method to protect against malicious code.', 'kb-doc-14-nist-sp-800-53-p375-3', 0, 32, '14-nist-sp-800-53', 'retrieved', '06022046DD351DB500AD9F520153FD2C98267745E0BAB345BFD91697C53143EF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
