INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p375-4', 'doc-14-nist-sp-800-53', '', 375, 'Organizations that employ cryptographic mechanisms also consider cryptographic key management solutions.', 'kb-doc-14-nist-sp-800-53-p375-4', 0, 11, '14-nist-sp-800-53', 'retrieved', '1B3D989BEB0A4E93FAB30F78C4F7302C22B5F6D2C287B86323A35B8A6D820BD0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
