INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p375-6', 'doc-14-nist-sp-800-53', '', 375, '(16) SOFTWARE, FIRMWARE, AND INFORMATION INTEGRITY | TIME LIMIT ON PROCESS EXECUTION WITHOUT SUPERVISION Prohibit processes from executing without supervision for more than [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p375-6', 0, 27, '14-nist-sp-800-53', 'retrieved', '978D1D841A51613CF5C242193F47BB0ACE4DB8EB8AFE1400AAB100DE192D7232', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p375-7', 'doc-14-nist-sp-800-53', '', 375, 'Discussion: Placing a time limit on process execution without supervision is intended to apply to processes for which typical or normal execution periods can be determined and situations in which organizations exceed such periods. Supervision includes timers on operating systems, automated responses, and manual oversight and response when system process anomalies occur.', 'kb-doc-14-nist-sp-800-53-p375-7', 0, 52, '14-nist-sp-800-53', 'retrieved', '75736881003FC8F07DA3D25C7E991F0804E23A87D109D39531E726D177BD869D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
