VALUES ('doc-14-nist-sp-800-53-p375-12', 'doc-14-nist-sp-800-53', '', 375, 'References: [OMB A-130], [FIPS 140-3], [FIPS 180-4], [FIPS 186-4], [FIPS 202], [SP 800-70], [SP 800-147].', 'kb-doc-14-nist-sp-800-53-p375-12', 0, 15, '14-nist-sp-800-53', 'retrieved', 'B172ACDE3A675B476224763FF3A58ED0547245CFA23D41D54C0F524B760E5E06', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
