VALUES ('doc-14-nist-sp-800-53-p376-1', 'doc-14-nist-sp-800-53', '', 376, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 349 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p376-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '90ADA5D28C3A2CA6C8C16658FC92B43C9F16C3C2D32C0FCC976D6A565587DEFE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
