INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-2', 'doc-14-nist-sp-800-53', '', 376, 'a. Employ spam protection mechanisms at system entry and exit points to detect and act on unsolicited messages; and b. Update spam protection mechanisms when new releases are available in accordance with organizational configuration management policy and procedures.', 'kb-doc-14-nist-sp-800-53-p376-2', 0, 38, '14-nist-sp-800-53', 'retrieved', 'ABCDBF23723C15F0891F812347925FD5A56F72EAAC5BA230F234EFB6E285D29D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
