INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-3', 'doc-14-nist-sp-800-53', '', 376, 'Discussion: System entry and exit points include firewalls, remote-access servers, electronic mail servers, web servers, proxy servers, workstations, notebook computers, and mobile devices.', 'kb-doc-14-nist-sp-800-53-p376-3', 0, 23, '14-nist-sp-800-53', 'retrieved', '16FACBDB14E7E67B593E8F6ED0B28EE24DDBBCC799BBE6182B19EC4A88513B75', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
