INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-4', 'doc-14-nist-sp-800-53', '', 376, 'Spam can be transported by different means, including email, email attachments, and web accesses. Spam protection mechanisms include signature definitions.', 'kb-doc-14-nist-sp-800-53-p376-4', 0, 20, '14-nist-sp-800-53', 'retrieved', 'E22567C6366F9DD6D31EF177D7E64CDA0A836B8C6058B19582CD31D1D10D851D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
