INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-6', 'doc-14-nist-sp-800-53', '', 376, 'Control Enhancements: (1) SPAM PROTECTION | CENTRAL MANAGEMENT [Withdrawn: Incorporated into PL-9.] (2) SPAM PROTECTION | AUTOMATIC UPDATES Automatically update spam protection mechanisms [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p376-6', 0, 26, '14-nist-sp-800-53', 'retrieved', '45894B0AC6B8F76EE74B9E7B1CDEE339BAFD6A7A86E5855405AE2E88972672E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
