INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p376-7', 'doc-14-nist-sp-800-53', '', 376, 'Discussion: Using automated mechanisms to update spam protection mechanisms helps to ensure that updates occur on a regular basis and provide the latest content and protection capabilities.', 'kb-doc-14-nist-sp-800-53-p376-7', 0, 27, '14-nist-sp-800-53', 'retrieved', '0D4EF570F7611A29DE85807EB4EF79F38B86DB8A57FE65D34D09D4A5AD8C1732', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
