VALUES ('doc-14-nist-sp-800-53-p376-9', 'doc-14-nist-sp-800-53', '', 376, '(3) SPAM PROTECTION |CONTINUOUS LEARNING CAPABILITY Implement spam protection mechanisms with a learning capability to more effectively identify legitimate communications traffic.', 'kb-doc-14-nist-sp-800-53-p376-9', 0, 21, '14-nist-sp-800-53', 'retrieved', '829557AEA4A6932FA486AB15EF3DB5849193580525639761CC998ECBC3AD0CBD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
